-- OrganizationService.availablePlans: ADM, published kind/domain-compatible offers.
CREATE PROCEDURE dbo.usp_organization_plans
AS
BEGIN
 SET NOCOUNT ON; SET XACT_ABORT ON;
 DECLARE @t char(36)=CONVERT(char(36),SESSION_CONTEXT(N'hp_tenant_id')); IF @t IS NULL THROW 51001,'HP_FORBIDDEN:Host tenant requerido',1; EXEC dbo.usp_org_target @t; SELECT p.id,p.name,p.description,p.status,p.current_version,v.plan_id,v.version,v.base_minor,v.branch_minor,v.professional_minor,v.included_branches,v.included_professionals,v.included_specialties,v.max_branches,v.max_professionals,v.max_specialties,v.annual_discount,v.kinds,v.domains,v.modules,v.created_at FROM dbo.plans p JOIN dbo.plan_versions v ON v.plan_id=p.id AND v.version=p.current_version JOIN dbo.tenants t ON t.id=@t WHERE p.status='PUBLISHED' AND EXISTS(SELECT 1 FROM OPENJSON(v.kinds) WHERE value=t.kind) AND EXISTS(SELECT 1 FROM OPENJSON(v.domains) WHERE value=t.domain) ORDER BY p.name,p.id;
END;
GO
-- PlatformService.plan / V6 sp_plan_save: immutable version append, current pointer changes under lock; no expectedRevision in API. RS plan/current version.
CREATE PROCEDURE dbo.usp_saas_plan_save @plan_id char(36),@input nvarchar(max),@create bit=0
AS
BEGIN
 SET NOCOUNT ON; SET XACT_ABORT ON;
 EXEC dbo.usp_require_actor @roles=N'SAD',@platform_only=1; EXEC dbo.usp_saas_write_gate;
 EXEC dbo.usp_org_json_object @input,N'{"name":1,"description":1,"status":1,"baseMinor":2,"branchMinor":2,"professionalMinor":2,"includedBranches":2,"includedProfessionals":2,"includedSpecialties":2,"maxBranches":2,"maxProfessionals":2,"maxSpecialties":2,"annualDiscount":2,"kinds":4,"domains":4,"modules":4}';
 DECLARE @name nvarchar(max),@description nvarchar(max),@status nvarchar(max),@base bigint,@branch bigint,@professional bigint,@ib int,@ip int,@is int,@mb int,@mp int,@ms int,@discount int,@kinds nvarchar(max),@domains nvarchar(max),@modules nvarchar(max),@ver int;
 SELECT @name=name,@description=description,@status=status,@base=TRY_CONVERT(bigint,base),@branch=TRY_CONVERT(bigint,branch),@professional=TRY_CONVERT(bigint,professional),@ib=TRY_CONVERT(int,ib),@ip=TRY_CONVERT(int,ip),@is=TRY_CONVERT(int,ins),@mb=TRY_CONVERT(int,mb),@mp=TRY_CONVERT(int,mp),@ms=TRY_CONVERT(int,ms),@discount=TRY_CONVERT(int,discount),@kinds=kinds,@domains=domains,@modules=modules FROM OPENJSON(@input) WITH(name nvarchar(max),description nvarchar(max),status nvarchar(max),base nvarchar(max) '$.baseMinor',branch nvarchar(max) '$.branchMinor',professional nvarchar(max) '$.professionalMinor',ib nvarchar(max) '$.includedBranches',ip nvarchar(max) '$.includedProfessionals',ins nvarchar(max) '$.includedSpecialties',mb nvarchar(max) '$.maxBranches',mp nvarchar(max) '$.maxProfessionals',ms nvarchar(max) '$.maxSpecialties',discount nvarchar(max) '$.annualDiscount',kinds nvarchar(max) AS JSON,domains nvarchar(max) AS JSON,modules nvarchar(max) AS JSON);
 IF @create IS NULL OR @plan_id IS NULL OR NULLIF(LTRIM(RTRIM(@name)),N'') IS NULL OR DATALENGTH(@name)>200 OR DATALENGTH(@description)>1000 OR DATALENGTH(@status)<>2*LEN(@status) OR @status COLLATE Latin1_General_100_BIN2 NOT IN ('DRAFT','PUBLISHED','ARCHIVED') OR @base IS NULL OR @branch IS NULL OR @professional IS NULL OR @base NOT BETWEEN 0 AND 1000000000000 OR @branch NOT BETWEEN 0 AND 1000000000000 OR @professional NOT BETWEEN 0 AND 1000000000000 OR @ib IS NULL OR @ip IS NULL OR @is IS NULL OR @mb IS NULL OR @mp IS NULL OR @ms IS NULL OR @discount IS NULL OR @ib<1 OR @ip<1 OR @is<1 OR @mb<@ib OR @mp<@ip OR @ms<@is OR @mb>10000 OR @mp>100000 OR @ms>241 OR @discount NOT BETWEEN 0 AND 60 THROW 51000,'HP_INVALID:Oferta o limites invalidos',1;
 EXEC dbo.usp_org_json_strings @kinds,40,N'["DOCTOR","CLINIC","HOSPITAL","VETERINARY","DENTAL","SPECIALTY_CENTER"]'; EXEC dbo.usp_org_json_strings @domains,6,N'["HUMAN","ANIMAL"]'; EXEC dbo.usp_org_json_strings @modules,40,N'["CORE","PORTAL","DENTAL","DIAGNOSTICS","PHARMACY","FINANCE","INVENTORY","HOSPITAL","SURGERY","ADVANCED","VET_POPULATION","REPORTS"]';
 IF NOT EXISTS(SELECT 1 FROM OPENJSON(@modules) WHERE value COLLATE Latin1_General_100_BIN2='CORE') OR EXISTS(SELECT 1 FROM OPENJSON(@kinds) WHERE value='DOCTOR') AND @ip<>1 THROW 51000,'HP_INVALID:CORE requerido e independiente con una identidad',1;
 SELECT @ver=current_version FROM dbo.plans WITH(UPDLOCK,HOLDLOCK) WHERE id=@plan_id; IF @create=1 AND @ver IS NOT NULL THROW 51003,'HP_CONFLICT:Oferta existente',1; IF @create=0 AND @ver IS NULL THROW 51002,'HP_NOT_FOUND:Oferta inexistente',1;
 IF EXISTS(SELECT 1 FROM dbo.plans WITH(UPDLOCK,HOLDLOCK) WHERE name=@name AND id<>@plan_id) THROW 51003,'HP_CONFLICT:Nombre de oferta utilizado',1;
 SET @ver=COALESCE(@ver,0)+1; IF @create=1 INSERT dbo.plans(id,name,description,status,current_version) VALUES(@plan_id,@name,@description,@status,@ver); ELSE UPDATE dbo.plans SET name=@name,description=@description,status=@status,current_version=@ver WHERE id=@plan_id;
 INSERT dbo.plan_versions(plan_id,version,base_minor,branch_minor,professional_minor,included_branches,included_professionals,included_specialties,max_branches,max_professionals,max_specialties,annual_discount,kinds,domains,modules) VALUES(@plan_id,@ver,@base,@branch,@professional,@ib,@ip,@is,@mb,@mp,@ms,@discount,@kinds,@domains,@modules);
 DECLARE @meta nvarchar(max)=(SELECT @ver version FOR JSON PATH,WITHOUT_ARRAY_WRAPPER); EXEC dbo.usp_audit_event NULL,N'PLAN_VERSION_CREATED',@plan_id,@meta; EXEC dbo.usp_platform_plans @plan_id;
END;
GO

-- PRIVATE V2 sp_subscription_validate: locks selected current published version. Public derives MONTHLY and included quotas server-side; no client-selected version.
CREATE PROCEDURE dbo.usp_org_subscription_resolve @input nvarchar(max),@kind nvarchar(40),@domain nvarchar(6),@public bit,@plan_id char(36) OUTPUT,@version int OUTPUT,@cycle nvarchar(7) OUTPUT,@branch_quota int OUTPUT,@professional_quota int OUTPUT,@specialty_quota int OUTPUT,@modules nvarchar(max) OUTPUT
AS
BEGIN
 SET NOCOUNT ON; SET XACT_ABORT ON;
 EXEC dbo.usp_require_transaction;
 EXEC dbo.usp_org_json_object @input,N'{"planId":1,"cycle":1,"branchQuota":2,"professionalQuota":2,"specialtyQuota":2}';
 DECLARE @pid nvarchar(max),@cy nvarchar(max),@b nvarchar(max),@pr nvarchar(max),@sc nvarchar(max),@ib int,@ip int,@mb int,@mp int,@ms int,@ins int,@k nvarchar(max),@d nvarchar(max);
 SELECT @pid=planId,@cy=cycle,@b=b,@pr=pr,@sc=sc FROM OPENJSON(@input) WITH(planId nvarchar(max),cycle nvarchar(max),b nvarchar(max) '$.branchQuota',pr nvarchar(max) '$.professionalQuota',sc nvarchar(max) '$.specialtyQuota');
 IF DATALENGTH(@pid)<>72 OR TRY_CONVERT(uniqueidentifier,@pid) IS NULL THROW 51000,'HP_INVALID:Plan invalido',1;
 SET @plan_id=CONVERT(char(36),@pid); SET @version=NULL;
 SELECT @version=p.current_version,@ib=v.included_branches,@ip=v.included_professionals,@ins=v.included_specialties,@mb=v.max_branches,@mp=v.max_professionals,@ms=v.max_specialties,@k=v.kinds,@d=v.domains,@modules=v.modules FROM dbo.plans p WITH(HOLDLOCK) JOIN dbo.plan_versions v WITH(HOLDLOCK) ON v.plan_id=p.id AND v.version=p.current_version WHERE p.id=@plan_id AND p.status='PUBLISHED';
 IF @version IS NULL OR NOT EXISTS(SELECT 1 FROM OPENJSON(@k) WHERE value COLLATE Latin1_General_100_BIN2=@kind COLLATE Latin1_General_100_BIN2) OR NOT EXISTS(SELECT 1 FROM OPENJSON(@d) WHERE value COLLATE Latin1_General_100_BIN2=@domain COLLATE Latin1_General_100_BIN2) THROW 51000,'HP_INVALID:Plan no publicado o incompatible',1;
 SET @branch_quota=CASE WHEN @public=1 THEN @ib ELSE TRY_CONVERT(int,@b) END; SET @professional_quota=CASE WHEN @public=1 THEN @ip ELSE TRY_CONVERT(int,@pr) END; SET @specialty_quota=CASE WHEN @public=1 THEN @ins ELSE TRY_CONVERT(int,@sc) END; SET @cycle=CASE WHEN @public=1 THEN 'MONTHLY' ELSE @cy END;
 IF @branch_quota IS NULL OR @professional_quota IS NULL OR @specialty_quota IS NULL OR @branch_quota NOT BETWEEN @ib AND @mb OR @professional_quota NOT BETWEEN @ip AND @mp OR @specialty_quota NOT BETWEEN 1 AND @ms OR @cy COLLATE Latin1_General_100_BIN2 NOT IN ('MONTHLY','YEARLY') OR (@kind='DOCTOR' AND @professional_quota<>1) THROW 51003,'HP_CONFLICT:HP_QUOTA Capacidad fuera de limites del plan',1;
 IF DATALENGTH(@cy)<>2*LEN(@cy) OR (@public=0 AND DATALENGTH(@cy)>14) THROW 51000,'HP_INVALID:Ciclo invalido',1;
END;
GO

-- PRIVATE V2 sp_specialties_validate: catalog codes/domain/DENTAL/selected count, no clinical activation implied.
CREATE PROCEDURE dbo.usp_org_validate_specialties @codes nvarchar(max),@domain nvarchar(6),@kind nvarchar(40),@quota int,@modules nvarchar(max)
AS
BEGIN
 SET NOCOUNT ON; SET XACT_ABORT ON;
 EXEC dbo.usp_org_json_strings @codes,100; IF (SELECT COUNT(*) FROM OPENJSON(@codes))>@quota THROW 51003,'HP_CONFLICT:HP_QUOTA Cupo de especialidades excedido',1; IF EXISTS(SELECT 1 FROM OPENJSON(@codes) j LEFT JOIN dbo.specialties s ON s.code=j.value COLLATE Latin1_General_100_BIN2 WHERE s.code IS NULL OR s.domain<>@domain OR (@kind='DENTAL' AND s.dental=0)) THROW 51000,'HP_INVALID:Perfil o dominio incompatible',1; IF EXISTS(SELECT 1 FROM OPENJSON(@codes) j JOIN dbo.specialties s ON s.code=j.value COLLATE Latin1_General_100_BIN2 WHERE s.dental=1) AND NOT EXISTS(SELECT 1 FROM OPENJSON(@modules) WHERE value COLLATE Latin1_General_100_BIN2='DENTAL') THROW 51001,'HP_FORBIDDEN:El perfil requiere modulo odontologico',1;
END;
GO
-- PlatformService.create + AccountLifecycleService.register / V2 sp_tenant_create: owner resolved by Spring new/existing XOR in same TX; public only pending fresh owner, server included quotas/MONTHLY. IANA ZoneId validation remains Spring. RS tenant (SAD) or public created scope. No expectedRevision exists.
CREATE PROCEDURE dbo.usp_saas_tenant_create @tenant_id char(36),@branch_id char(36),@owner_id char(36),@input nvarchar(max)
AS
BEGIN
 SET NOCOUNT ON; SET XACT_ABORT ON;
 EXEC dbo.usp_saas_write_gate;
 DECLARE @public bit=CASE WHEN CONVERT(varchar(20),SESSION_CONTEXT(N'hp_scope'))='IDENTITY' AND SESSION_CONTEXT(N'hp_actor_id') IS NULL AND SESSION_CONTEXT(N'hp_tenant_id') IS NULL THEN 1 ELSE 0 END;
 IF @public=0 EXEC dbo.usp_require_actor @roles=N'SAD',@platform_only=1;
 EXEC dbo.usp_org_json_object @input,N'{"name":1,"slug":1,"kind":1,"domain":1,"timezone":1,"branchName":1,"address":1,"specialties":4,"subscription":5}';
 DECLARE @name nvarchar(max),@slug nvarchar(max),@kind nvarchar(max),@domain nvarchar(max),@zone nvarchar(max),@bname nvarchar(max),@address nvarchar(max),@codes nvarchar(max),@sub nvarchar(max),@pid char(36),@ver int,@cycle nvarchar(7),@b int,@pr int,@sc int,@modules nvarchar(max),@owner_domain nvarchar(6),@verified bit,@user_exists char(36);
 SELECT @name=name,@slug=slug,@kind=kind,@domain=domain,@zone=timezone,@bname=branchName,@address=address,@codes=specialties,@sub=subscription FROM OPENJSON(@input) WITH(name nvarchar(max),slug nvarchar(max),kind nvarchar(max),domain nvarchar(max),timezone nvarchar(max),branchName nvarchar(max),address nvarchar(max),specialties nvarchar(max) AS JSON,subscription nvarchar(max) AS JSON);
 IF @tenant_id IS NULL OR @branch_id IS NULL OR @owner_id IS NULL OR NULLIF(LTRIM(RTRIM(@name)),N'') IS NULL OR DATALENGTH(@name)>320 OR NULLIF(LTRIM(RTRIM(@bname)),N'') IS NULL OR DATALENGTH(@bname)>320 OR DATALENGTH(@address)>600 OR NULLIF(LTRIM(RTRIM(@zone)),N'') IS NULL OR DATALENGTH(@zone)>128 OR DATALENGTH(@kind)<>2*LEN(@kind) OR DATALENGTH(@domain)<>2*LEN(@domain) OR @kind COLLATE Latin1_General_100_BIN2 NOT IN ('DOCTOR','CLINIC','HOSPITAL','VETERINARY','DENTAL','SPECIALTY_CENTER') OR @domain COLLATE Latin1_General_100_BIN2 NOT IN ('HUMAN','ANIMAL') OR (@kind='VETERINARY' AND @domain<>'ANIMAL') OR (@kind NOT IN ('DOCTOR','VETERINARY') AND @domain<>'HUMAN') THROW 51000,'HP_INVALID:Datos de organizacion invalidos',1;
 IF LEN(@slug) NOT BETWEEN 1 AND 63 OR DATALENGTH(@slug)<>2*LEN(@slug) OR @slug COLLATE Latin1_General_100_BIN2 LIKE N'%[^a-z0-9-]%' OR LEFT(@slug,1)='-' OR RIGHT(@slug,1)='-' OR @slug LIKE N'%--%' OR @slug IN ('www','admin','api','app','saas','mail','support','status','auth','portal','localhost') THROW 51000,'HP_INVALID:Subdominio invalido o reservado',1;
 SELECT @user_exists=id,@owner_domain=clinical_domain,@verified=email_verified FROM dbo.users WITH(UPDLOCK,HOLDLOCK) WHERE id=@owner_id AND active=1 AND platform_role IS NULL;
 IF @user_exists IS NULL OR (@kind='DOCTOR' AND (@owner_domain IS NULL OR @owner_domain<>@domain)) THROW 51000,'HP_INVALID:Propietario o dominio incompatible',1;
 IF @public=1 AND (@verified<>0 OR EXISTS(SELECT 1 FROM dbo.memberships WITH(UPDLOCK,HOLDLOCK) WHERE user_id=@owner_id) OR EXISTS(SELECT 1 FROM dbo.tenants WITH(UPDLOCK,HOLDLOCK) WHERE owner_user_id=@owner_id)) THROW 51001,'HP_FORBIDDEN:El registro requiere identidad nueva sin membresias',1;
 IF EXISTS(SELECT 1 FROM dbo.branches WITH(UPDLOCK,HOLDLOCK) WHERE id=@branch_id) THROW 51003,'HP_CONFLICT:Identificador de sede existente',1; IF EXISTS(SELECT 1 FROM dbo.tenants WITH(UPDLOCK,HOLDLOCK) WHERE slug=@slug OR id=@tenant_id) THROW 51003,'HP_CONFLICT:Subdominio o cliente existente',1;
 EXEC dbo.usp_org_subscription_resolve @sub,@kind,@domain,@public,@pid OUTPUT,@ver OUTPUT,@cycle OUTPUT,@b OUTPUT,@pr OUTPUT,@sc OUTPUT,@modules OUTPUT;
 EXEC dbo.usp_org_validate_specialties @codes,@domain,@kind,@sc,@modules;
 INSERT dbo.tenants(id,name,slug,kind,domain,owner_user_id,timezone) VALUES(@tenant_id,@name,@slug,@kind,@domain,@owner_id,@zone);
 INSERT dbo.subscriptions(tenant_id,plan_id,plan_version,cycle,branch_quota,professional_quota,specialty_quota,renewal_date) VALUES(@tenant_id,@pid,@ver,@cycle,@b,@pr,@sc,CONVERT(date,CASE WHEN @cycle='YEARLY' THEN DATEADD(year,1,SYSUTCDATETIME()) ELSE DATEADD(month,1,SYSUTCDATETIME()) END));
 INSERT dbo.branches(id,tenant_id,name,address,[external],active) VALUES(@branch_id,@tenant_id,@bname,@address,0,1);
 INSERT dbo.tenant_specialties(tenant_id,specialty_code) SELECT @tenant_id,value FROM OPENJSON(@codes);
 INSERT dbo.areas(id,tenant_id,branch_id,name,specialties) VALUES(CONVERT(char(36),NEWID()),@tenant_id,@branch_id,N'Consulta y atencion',@codes);
 INSERT dbo.memberships(tenant_id,user_id,roles,status,owner) VALUES(@tenant_id,@owner_id,CASE WHEN @kind='DOCTOR' THEN N'["ADM","PRO"]' ELSE N'["ADM"]' END,'ACTIVE',1);
 INSERT dbo.membership_branches(tenant_id,user_id,branch_id) VALUES(@tenant_id,@owner_id,@branch_id);
 IF @kind='DOCTOR' INSERT dbo.membership_specialties(tenant_id,user_id,specialty_code) SELECT @tenant_id,@owner_id,value FROM OPENJSON(@codes);
 DECLARE @meta nvarchar(max)=(SELECT @slug slug FOR JSON PATH,WITHOUT_ARRAY_WRAPPER); EXEC dbo.usp_audit_event @tenant_id,N'TENANT_CREATED',@tenant_id,@meta;
 IF @public=0 EXEC dbo.usp_platform_tenants @tenant_id; ELSE SELECT @tenant_id id,@tenant_id tenant_id,@slug slug,@kind kind,@domain domain,CAST('TRIAL' AS nvarchar(10)) status;
END;
GO

-- PlatformService.status / V2: recovery from suspended/cancelled allowed, global OPEN required; no optimistic revision in current DTO.
CREATE PROCEDURE dbo.usp_saas_tenant_status @tenant_id char(36),@status nvarchar(10),@reason nvarchar(max)
AS
BEGIN
 SET NOCOUNT ON; SET XACT_ABORT ON;
 EXEC dbo.usp_require_actor @roles=N'SAD',@platform_only=1; EXEC dbo.usp_saas_write_gate; IF @status IS NULL OR DATALENGTH(@status)<>2*LEN(@status) OR @status COLLATE Latin1_General_100_BIN2 NOT IN ('TRIAL','ACTIVE','SUSPENDED','CANCELLED') OR NULLIF(LTRIM(RTRIM(@reason)),N'') IS NULL OR DATALENGTH(@reason)>1000 THROW 51000,'HP_INVALID:Estado y motivo requeridos',1; UPDATE dbo.tenants WITH(UPDLOCK,HOLDLOCK) SET status=@status WHERE id=@tenant_id; IF @@ROWCOUNT<>1 THROW 51002,'HP_NOT_FOUND:Organizacion inexistente',1; DECLARE @meta nvarchar(max)=(SELECT @status status,@reason reason FOR JSON PATH,WITHOUT_ARRAY_WRAPPER); EXEC dbo.usp_audit_event @tenant_id,N'TENANT_STATUS_CHANGED',@tenant_id,@meta; EXEC dbo.usp_platform_tenants @tenant_id;
END;
GO

-- OrganizationService.subscription / V2: locked tenant serializes consumption; snapshots old plan versions/invoices preserved. RS eight configuration sets, no tenant auto-resume; no expectedRevision in API.
CREATE PROCEDURE dbo.usp_organization_subscription_change @tenant_id char(36),@invoice_id char(36),@input nvarchar(max)
AS
BEGIN
 SET NOCOUNT ON; SET XACT_ABORT ON;
 IF @invoice_id IS NULL THROW 51000,'HP_INVALID:Comprobante requerido',1; DECLARE @require_active bit=CASE WHEN SESSION_CONTEXT(N'hp_tenant_id') IS NULL THEN 0 ELSE 1 END; EXEC dbo.usp_org_target @tenant_id,@write=1,@require_active=@require_active;
 DECLARE @kind nvarchar(40),@domain nvarchar(6),@pid char(36),@ver int,@cycle nvarchar(7),@b int,@pr int,@sc int,@modules nvarchar(max),@amount decimal(38,0),@base bigint,@br bigint,@pro bigint,@ib int,@ip int,@discount int;
 SELECT @kind=kind,@domain=domain FROM dbo.tenants WHERE id=@tenant_id;
 EXEC dbo.usp_org_subscription_resolve @input,@kind,@domain,0,@pid OUTPUT,@ver OUTPUT,@cycle OUTPUT,@b OUTPUT,@pr OUTPUT,@sc OUTPUT,@modules OUTPUT;
 IF @b<(SELECT COUNT_BIG(*) FROM dbo.branches WHERE tenant_id=@tenant_id AND active=1 AND [external]=0) OR @pr<(SELECT COUNT_BIG(*) FROM dbo.memberships m WHERE m.tenant_id=@tenant_id AND m.status<>'INACTIVE' AND EXISTS(SELECT 1 FROM OPENJSON(m.roles) WHERE value='PRO')) OR @sc<(SELECT COUNT_BIG(*) FROM dbo.tenant_specialties WHERE tenant_id=@tenant_id) THROW 51003,'HP_CONFLICT:HP_QUOTA Contrato inferior al consumo',1;
 IF EXISTS(SELECT 1 FROM dbo.tenant_specialties ts JOIN dbo.specialties s ON s.code=ts.specialty_code WHERE ts.tenant_id=@tenant_id AND s.dental=1) AND NOT EXISTS(SELECT 1 FROM OPENJSON(@modules) WHERE value='DENTAL') THROW 51001,'HP_FORBIDDEN:Conserva modulo odontologico de perfiles asignados',1;
 SELECT @base=base_minor,@br=branch_minor,@pro=professional_minor,@ib=included_branches,@ip=included_professionals,@discount=annual_discount FROM dbo.plan_versions WHERE plan_id=@pid AND version=@ver;
 SET @amount=CONVERT(decimal(38,0),@base)+CONVERT(decimal(38,0),CASE WHEN @b>@ib THEN @b-@ib ELSE 0 END)*@br+CONVERT(decimal(38,0),CASE WHEN @pr>@ip THEN @pr-@ip ELSE 0 END)*@pro;
 IF @cycle='YEARLY' SET @amount=FLOOR((@amount*12*(100-@discount)+50)/100);
 IF @amount>9223372036854775807 THROW 51000,'HP_INVALID:Importe fuera de rango',1;
 UPDATE dbo.subscriptions SET plan_id=@pid,plan_version=@ver,cycle=@cycle,branch_quota=@b,professional_quota=@pr,specialty_quota=@sc,renewal_date=CONVERT(date,CASE WHEN @cycle='YEARLY' THEN DATEADD(year,1,SYSUTCDATETIME()) ELSE DATEADD(month,1,SYSUTCDATETIME()) END) WHERE tenant_id=@tenant_id;
 INSERT dbo.saas_invoices(id,tenant_id,amount_minor,cycle,status) VALUES(@invoice_id,@tenant_id,CONVERT(bigint,@amount),@cycle,'PENDING');
 DECLARE @meta nvarchar(max)=(SELECT @pid planId,@ver version FOR JSON PATH,WITHOUT_ARRAY_WRAPPER); EXEC dbo.usp_audit_event @tenant_id,N'SUBSCRIPTION_CHANGED',@tenant_id,@meta; EXEC dbo.usp_organization_configuration @tenant_id;
END;
GO

-- PlatformService.pay / V2: idempotent internal SaaS payment marker only; no external payment provider or clinical finance side effects.
CREATE PROCEDURE dbo.usp_saas_invoice_pay @tenant_id char(36),@invoice_id char(36)
AS
BEGIN
 SET NOCOUNT ON; SET XACT_ABORT ON;
 EXEC dbo.usp_require_actor @roles=N'SAD',@platform_only=1; EXEC dbo.usp_saas_write_gate; DECLARE @state nvarchar(7); SELECT @state=status FROM dbo.saas_invoices WITH(UPDLOCK,HOLDLOCK) WHERE tenant_id=@tenant_id AND id=@invoice_id; IF @state IS NULL THROW 51002,'HP_NOT_FOUND:Comprobante inexistente',1; IF @state='PENDING' BEGIN UPDATE dbo.saas_invoices SET status='PAID',paid_at=SYSUTCDATETIME() WHERE tenant_id=@tenant_id AND id=@invoice_id; EXEC dbo.usp_audit_event @tenant_id,N'SAAS_PAYMENT_RECORDED',@invoice_id; END; SELECT id,tenant_id,amount_minor,currency,cycle,status,created_at,paid_at FROM dbo.saas_invoices WHERE tenant_id=@tenant_id AND id=@invoice_id;
END;
GO
-- OrganizationService.branch / active V6: same-tenant POST/PUT existence, quota and last owned active branch, external DOCTOR-owner, pending operations block deactivation. RS Branch; API has no revision.
CREATE PROCEDURE dbo.usp_organization_branch_save @tenant_id char(36),@branch_id char(36),@input nvarchar(max),@create bit=0
AS
BEGIN
 SET NOCOUNT ON; SET XACT_ABORT ON;
 EXEC dbo.usp_org_target @tenant_id,@write=1; EXEC dbo.usp_org_json_object @input,N'{"name":1,"address":1,"external":3,"active":3}';
 DECLARE @name nvarchar(max),@address nvarchar(max),@ext bit,@active bit,@kind nvarchar(40),@owner char(36),@quota int,@used int,@oldactive bit,@oldext bit;
 SELECT @name=name,@address=address,@ext=CASE WHEN [external]='true' THEN 1 ELSE 0 END,@active=CASE WHEN active='true' THEN 1 ELSE 0 END FROM OPENJSON(@input) WITH(name nvarchar(max),address nvarchar(max),[external] nvarchar(max),active nvarchar(max));
 IF @branch_id IS NULL OR NULLIF(LTRIM(RTRIM(@name)),N'') IS NULL OR DATALENGTH(@name)>320 OR DATALENGTH(@address)>600 OR @create IS NULL THROW 51000,'HP_INVALID:Datos de sede invalidos',1;
 SELECT @kind=kind,@owner=owner_user_id FROM dbo.tenants WHERE id=@tenant_id; SELECT @quota=branch_quota FROM dbo.subscriptions WHERE tenant_id=@tenant_id;
 IF @ext=1 AND (@kind<>'DOCTOR' OR (SESSION_CONTEXT(N'hp_tenant_id') IS NOT NULL AND CONVERT(char(36),SESSION_CONTEXT(N'hp_actor_id'))<>@owner)) THROW 51001,'HP_FORBIDDEN:Lugar externo solo para propietario independiente',1;
 IF EXISTS(SELECT 1 FROM dbo.branches WHERE id=@branch_id AND tenant_id<>@tenant_id) THROW 51002,'HP_NOT_FOUND:Sede inexistente',1;
 SELECT @oldactive=active,@oldext=[external] FROM dbo.branches WITH(UPDLOCK,HOLDLOCK) WHERE tenant_id=@tenant_id AND id=@branch_id;
 IF @create=1 AND @oldactive IS NOT NULL THROW 51003,'HP_CONFLICT:Sede existente',1; IF @create=0 AND @oldactive IS NULL THROW 51002,'HP_NOT_FOUND:Sede inexistente',1;
 SELECT @used=COUNT(*) FROM dbo.branches WHERE tenant_id=@tenant_id AND active=1 AND [external]=0;
 IF (@oldactive IS NULL OR @oldactive=0 OR @oldext=1) AND @active=1 AND @ext=0 AND @used>=@quota THROW 51003,'HP_CONFLICT:HP_QUOTA No hay capacidad de sedes',1;
 IF @oldactive=1 AND @oldext=0 AND (@active=0 OR @ext=1) AND @used<=1 THROW 51000,'HP_INVALID:Debe quedar una sede propia activa',1;
 IF @oldactive=1 AND @active=0 AND (EXISTS(SELECT 1 FROM dbo.appointments WHERE tenant_id=@tenant_id AND branch_id=@branch_id AND status NOT IN ('CANCELLED','WITHDRAWN','COMPLETED')) OR EXISTS(SELECT 1 FROM dbo.encounters WHERE tenant_id=@tenant_id AND branch_id=@branch_id AND status<>'FINALIZED') OR EXISTS(SELECT 1 FROM dbo.admissions a JOIN dbo.hospital_resources r ON r.tenant_id=a.tenant_id AND r.id=a.resource_id WHERE a.tenant_id=@tenant_id AND r.branch_id=@branch_id AND a.status='ADMITTED') OR EXISTS(SELECT 1 FROM dbo.stock_transfers x JOIN dbo.stock_lots l ON l.tenant_id=x.tenant_id AND l.id=x.lot_id WHERE x.tenant_id=@tenant_id AND x.status='IN_TRANSIT' AND (x.destination_branch_id=@branch_id OR l.branch_id=@branch_id)) OR EXISTS(SELECT 1 FROM dbo.stock_lots WHERE tenant_id=@tenant_id AND branch_id=@branch_id AND quantity>0) OR EXISTS(SELECT 1 FROM dbo.workflow_cases WHERE tenant_id=@tenant_id AND branch_id=@branch_id AND status NOT IN ('COMPLETED','CANCELLED'))) THROW 51003,'HP_CONFLICT:La sede mantiene operaciones o stock pendientes',1;
 IF EXISTS(SELECT 1 FROM dbo.branches WHERE tenant_id=@tenant_id AND name=@name AND id<>@branch_id) THROW 51003,'HP_CONFLICT:Nombre de sede utilizado',1;
 IF @create=1 INSERT dbo.branches(id,tenant_id,name,address,[external],active) VALUES(@branch_id,@tenant_id,@name,@address,@ext,@active); ELSE UPDATE dbo.branches SET name=@name,address=@address,[external]=@ext,active=@active WHERE tenant_id=@tenant_id AND id=@branch_id;
 DECLARE @meta nvarchar(max)=(SELECT @active active FOR JSON PATH,WITHOUT_ARRAY_WRAPPER); EXEC dbo.usp_audit_event @tenant_id,N'BRANCH_SAVED',@branch_id,@meta; SELECT id,tenant_id,name,address,[external],active FROM dbo.branches WHERE tenant_id=@tenant_id AND id=@branch_id;
END;
GO

-- OrganizationService.area / V2: own active branch and activated specialties; no expectedRevision exists. RS Area JSON specialties.
CREATE PROCEDURE dbo.usp_organization_area_save @tenant_id char(36),@area_id char(36),@input nvarchar(max),@create bit=0
AS
BEGIN
 SET NOCOUNT ON; SET XACT_ABORT ON;
 EXEC dbo.usp_org_target @tenant_id,@write=1; EXEC dbo.usp_org_json_object @input,N'{"branchId":1,"name":1,"specialties":4}'; DECLARE @branch nvarchar(max),@name nvarchar(max),@codes nvarchar(max); SELECT @branch=branchId,@name=name,@codes=specialties FROM OPENJSON(@input) WITH(branchId nvarchar(max),name nvarchar(max),specialties nvarchar(max) AS JSON); IF @area_id IS NULL OR @create IS NULL OR DATALENGTH(@branch)<>72 OR TRY_CONVERT(uniqueidentifier,@branch) IS NULL OR NULLIF(LTRIM(RTRIM(@name)),N'') IS NULL OR DATALENGTH(@name)>320 THROW 51000,'HP_INVALID:Datos de area invalidos',1; IF NOT EXISTS(SELECT 1 FROM dbo.branches WHERE tenant_id=@tenant_id AND id=@branch AND active=1) THROW 51002,'HP_NOT_FOUND:Sede no disponible',1; EXEC dbo.usp_org_json_strings @codes,100; IF EXISTS(SELECT 1 FROM OPENJSON(@codes) j WHERE NOT EXISTS(SELECT 1 FROM dbo.tenant_specialties ts WHERE ts.tenant_id=@tenant_id AND ts.specialty_code=j.value COLLATE Latin1_General_100_BIN2)) THROW 51000,'HP_INVALID:Especialidad no activada en la organizacion',1; IF EXISTS(SELECT 1 FROM dbo.areas WHERE id=@area_id AND tenant_id<>@tenant_id) THROW 51002,'HP_NOT_FOUND:Area inexistente',1; IF @create=0 AND NOT EXISTS(SELECT 1 FROM dbo.areas WHERE tenant_id=@tenant_id AND id=@area_id) THROW 51002,'HP_NOT_FOUND:Area inexistente',1; IF @create=1 AND EXISTS(SELECT 1 FROM dbo.areas WHERE id=@area_id) THROW 51003,'HP_CONFLICT:Area existente',1; IF EXISTS(SELECT 1 FROM dbo.areas WHERE tenant_id=@tenant_id AND branch_id=@branch AND name=@name AND id<>@area_id) THROW 51003,'HP_CONFLICT:Nombre de area utilizado',1; IF @create=1 INSERT dbo.areas(id,tenant_id,branch_id,name,specialties) VALUES(@area_id,@tenant_id,@branch,@name,@codes); ELSE UPDATE dbo.areas SET branch_id=@branch,name=@name,specialties=@codes WHERE tenant_id=@tenant_id AND id=@area_id; EXEC dbo.usp_audit_event @tenant_id,N'AREA_SAVED',@area_id; SELECT id,tenant_id,branch_id,name,specialties FROM dbo.areas WHERE tenant_id=@tenant_id AND id=@area_id;
END;
GO

-- OrganizationService.specialties / V2: preserve referenced specialties including area assignments, no clinical activation certification. RS configuration.
CREATE PROCEDURE dbo.usp_organization_specialties_save @tenant_id char(36),@codes nvarchar(max)
AS
BEGIN
 SET NOCOUNT ON; SET XACT_ABORT ON;
 EXEC dbo.usp_org_target @tenant_id,@write=1; DECLARE @domain nvarchar(6),@kind nvarchar(40),@quota int,@modules nvarchar(max); SELECT @domain=t.domain,@kind=t.kind,@quota=s.specialty_quota,@modules=v.modules FROM dbo.tenants t JOIN dbo.subscriptions s ON s.tenant_id=t.id JOIN dbo.plan_versions v ON v.plan_id=s.plan_id AND v.version=s.plan_version WHERE t.id=@tenant_id; EXEC dbo.usp_org_validate_specialties @codes,@domain,@kind,@quota,@modules; IF EXISTS(SELECT 1 FROM dbo.membership_specialties m WHERE m.tenant_id=@tenant_id AND NOT EXISTS(SELECT 1 FROM OPENJSON(@codes) j WHERE j.value COLLATE Latin1_General_100_BIN2=m.specialty_code)) OR EXISTS(SELECT 1 FROM dbo.appointments a WHERE a.tenant_id=@tenant_id AND NOT EXISTS(SELECT 1 FROM OPENJSON(@codes) j WHERE j.value COLLATE Latin1_General_100_BIN2=a.specialty_code)) OR EXISTS(SELECT 1 FROM dbo.encounters e WHERE e.tenant_id=@tenant_id AND NOT EXISTS(SELECT 1 FROM OPENJSON(@codes) j WHERE j.value COLLATE Latin1_General_100_BIN2=e.specialty_code)) OR EXISTS(SELECT 1 FROM dbo.areas a CROSS APPLY OPENJSON(a.specialties) j WHERE a.tenant_id=@tenant_id AND NOT EXISTS(SELECT 1 FROM OPENJSON(@codes) selected WHERE selected.value COLLATE Latin1_General_100_BIN2=j.value COLLATE Latin1_General_100_BIN2)) THROW 51003,'HP_CONFLICT:Conserva perfiles con asignaciones o historia',1; DELETE dbo.tenant_specialties WHERE tenant_id=@tenant_id AND NOT EXISTS(SELECT 1 FROM OPENJSON(@codes) j WHERE j.value COLLATE Latin1_General_100_BIN2=specialty_code); INSERT dbo.tenant_specialties(tenant_id,specialty_code) SELECT @tenant_id,j.value FROM OPENJSON(@codes) j WHERE NOT EXISTS(SELECT 1 FROM dbo.tenant_specialties ts WHERE ts.tenant_id=@tenant_id AND ts.specialty_code=j.value COLLATE Latin1_General_100_BIN2); DECLARE @count int=(SELECT COUNT(*) FROM OPENJSON(@codes)),@meta nvarchar(max); SET @meta=(SELECT @count [count] FOR JSON PATH,WITHOUT_ARRAY_WRAPPER); EXEC dbo.usp_audit_event @tenant_id,N'SPECIALTIES_CONFIGURED',@tenant_id,@meta; EXEC dbo.usp_organization_configuration @tenant_id;
END;
GO

-- OrganizationService.member / V2: Spring resolves userId XOR newly created user in same TX via V3. Actual tenant lock serializes counted PRO active/invited; owner preserved, DOCTOR sole clinical identity. RS saved member; no revision in API.
CREATE PROCEDURE dbo.usp_organization_member_save @tenant_id char(36),@user_id char(36),@input nvarchar(max)
AS
BEGIN
 SET NOCOUNT ON; SET XACT_ABORT ON;
 EXEC dbo.usp_org_target @tenant_id,@write=1; EXEC dbo.usp_org_json_object @input,N'{"roles":4,"status":1,"branches":4,"specialties":4}'; DECLARE @roles nvarchar(max),@status nvarchar(max),@branches nvarchar(max),@codes nvarchar(max),@domain nvarchar(6),@kind nvarchar(40),@ownerid char(36),@quota int,@used int,@owner bit,@oldpro bit=0,@newpro bit=0,@userdomain nvarchar(6); SELECT @roles=roles,@status=status,@branches=branches,@codes=specialties FROM OPENJSON(@input) WITH(roles nvarchar(max) AS JSON,status nvarchar(max),branches nvarchar(max) AS JSON,specialties nvarchar(max) AS JSON); EXEC dbo.usp_org_json_strings @roles,3,N'["ADM","REC","PRO","ASI","DIA","FAR","CAJ","ALM","PAC","RES","AUD"]'; EXEC dbo.usp_org_json_strings @branches,36; EXEC dbo.usp_org_json_strings @codes,100,@nonempty=0; IF DATALENGTH(@status)<>2*LEN(@status) OR @status COLLATE Latin1_General_100_BIN2 NOT IN ('ACTIVE','INVITED','INACTIVE') THROW 51000,'HP_INVALID:Estado de miembro invalido',1; SELECT @domain=domain,@kind=kind,@ownerid=owner_user_id FROM dbo.tenants WHERE id=@tenant_id; SELECT @quota=professional_quota FROM dbo.subscriptions WHERE tenant_id=@tenant_id; IF NOT EXISTS(SELECT 1 FROM dbo.users WITH(UPDLOCK,HOLDLOCK) WHERE id=@user_id AND active=1 AND platform_role IS NULL) THROW 51002,'HP_NOT_FOUND:Identidad no disponible',1; SELECT @userdomain=clinical_domain FROM dbo.users WHERE id=@user_id; SELECT @owner=owner,@oldpro=CASE WHEN status<>'INACTIVE' AND EXISTS(SELECT 1 FROM OPENJSON(roles) WHERE value='PRO') THEN 1 ELSE 0 END FROM dbo.memberships WITH(UPDLOCK,HOLDLOCK) WHERE tenant_id=@tenant_id AND user_id=@user_id; IF EXISTS(SELECT 1 FROM OPENJSON(@roles) WHERE value='PRO') BEGIN IF (@status<>'INACTIVE' AND (@userdomain IS NULL OR @userdomain<>@domain)) OR (@kind='DOCTOR' AND @user_id<>@ownerid) THROW 51000,'HP_INVALID:Identidad profesional incompatible',1; IF @status<>'INACTIVE' SET @newpro=1; END; SELECT @used=COUNT(*) FROM dbo.memberships m WHERE m.tenant_id=@tenant_id AND m.status<>'INACTIVE' AND EXISTS(SELECT 1 FROM OPENJSON(m.roles) WHERE value='PRO'); IF @newpro=1 AND @oldpro=0 AND @used>=@quota THROW 51003,'HP_CONFLICT:HP_QUOTA Sin licencias profesionales disponibles',1; IF @owner=1 AND (@status<>'ACTIVE' OR NOT EXISTS(SELECT 1 FROM OPENJSON(@roles) WHERE value='ADM')) THROW 51000,'HP_INVALID:Conserva administrador propietario activo',1; IF EXISTS(SELECT 1 FROM OPENJSON(@branches) j WHERE DATALENGTH(j.value)<>72 OR TRY_CONVERT(uniqueidentifier,j.value) IS NULL OR NOT EXISTS(SELECT 1 FROM dbo.branches b WHERE b.tenant_id=@tenant_id AND b.id=j.value COLLATE Latin1_General_100_BIN2 AND b.active=1)) THROW 51000,'HP_INVALID:Asigna sedes activas del mismo tenant',1; IF EXISTS(SELECT 1 FROM OPENJSON(@roles) WHERE value='PRO') AND ((@newpro=1 AND NOT EXISTS(SELECT 1 FROM OPENJSON(@codes))) OR EXISTS(SELECT 1 FROM OPENJSON(@codes) j WHERE NOT EXISTS(SELECT 1 FROM dbo.tenant_specialties ts WHERE ts.tenant_id=@tenant_id AND ts.specialty_code=j.value COLLATE Latin1_General_100_BIN2))) THROW 51000,'HP_INVALID:Asigna especialidades activadas del tenant',1; IF NOT EXISTS(SELECT 1 FROM dbo.memberships WHERE tenant_id=@tenant_id AND user_id=@user_id) INSERT dbo.memberships(tenant_id,user_id,roles,status,owner) VALUES(@tenant_id,@user_id,@roles,@status,0); ELSE UPDATE dbo.memberships SET roles=@roles,status=@status WHERE tenant_id=@tenant_id AND user_id=@user_id; DELETE dbo.membership_branches WHERE tenant_id=@tenant_id AND user_id=@user_id; INSERT dbo.membership_branches(tenant_id,user_id,branch_id) SELECT @tenant_id,@user_id,value FROM OPENJSON(@branches); DELETE dbo.membership_specialties WHERE tenant_id=@tenant_id AND user_id=@user_id; IF EXISTS(SELECT 1 FROM OPENJSON(@roles) WHERE value='PRO') INSERT dbo.membership_specialties(tenant_id,user_id,specialty_code) SELECT @tenant_id,@user_id,value FROM OPENJSON(@codes); DECLARE @meta nvarchar(max)=(SELECT @status status FOR JSON PATH,WITHOUT_ARRAY_WRAPPER); EXEC dbo.usp_audit_event @tenant_id,N'MEMBERSHIP_SAVED',@user_id,@meta; SELECT u.id,u.name,u.email,u.clinical_domain,m.roles,m.status,m.owner FROM dbo.memberships m JOIN dbo.users u ON u.id=m.user_id WHERE m.tenant_id=@tenant_id AND m.user_id=@user_id;
END;
GO

-- PlatformService.createUser: saved user projection, no password hash and no extra active field.
CREATE PROCEDURE dbo.usp_platform_user @user_id char(36),@active_only bit=0
AS
BEGIN
 SET NOCOUNT ON; SET XACT_ABORT ON;
 EXEC dbo.usp_require_actor @roles=N'SAD',@platform_only=1;
 SELECT id,name,email,clinical_domain,credential FROM dbo.users WHERE id=@user_id AND (@active_only=0 OR active=1);
END;
GO

-- ==================== FIN V4__saas_organization_procedures.sql ====================

-- ==================== INICIO V5__clinical_procedures.sql ====================
-- SQL Server 2022. Tenant clinical persistence; NEVER grant runtime EXECUTE on private helpers.
-- All audited reads and mutations require the caller Spring transaction; no autonomous commits.
-- ClinicalValidation remains in Spring: these SPs validate JSON/ownership/state, not clinical correctness.
SET ANSI_NULLS ON;
SET QUOTED_IDENTIFIER ON;
GO
-- PRIVATE role/session/current membership guard: platform SAD/SOP always denied, even for history.
CREATE PROCEDURE dbo.usp_clinical_scope @roles nvarchar(200),@write bit=0,@module nvarchar(40)=N'CORE'
AS
BEGIN
 SET NOCOUNT ON; SET XACT_ABORT ON;
 EXEC dbo.usp_require_actor @roles; DECLARE @t char(36)=CONVERT(char(36),SESSION_CONTEXT(N'hp_tenant_id')); IF @t IS NULL THROW 51001,'HP_FORBIDDEN:Se requiere una sesion tenant',1; IF @write=1 EXEC dbo.usp_write_guard @t,@module;
END;
GO

-- PRIVATE Access.branch via accepted V3: current tenant active branch; ADM or assigned member. No nested INSERT EXEC callers.
CREATE PROCEDURE dbo.usp_clinical_branch_guard @branch_id char(36)
AS
BEGIN
 SET NOCOUNT ON; SET XACT_ABORT ON;
 DECLARE @ids TABLE(id char(36),branch_id char(36)); INSERT @ids EXEC dbo.usp_access_branch @branch_id; IF NOT EXISTS(SELECT 1 FROM @ids) THROW 51001,'HP_FORBIDDEN:Sede no disponible para esta membresia',1;
END;
GO

-- PRIVATE V3 sp_professional_guard: locks GLOBAL user identity, then validates current tenant assignment. Shared across every tenant reservation.
CREATE PROCEDURE dbo.usp_clinical_professional_guard @professional_id char(36),@branch_id char(36),@specialty_code varchar(100)
AS
BEGIN
 SET NOCOUNT ON; SET XACT_ABORT ON;
 EXEC dbo.usp_require_transaction; DECLARE @t char(36)=CONVERT(char(36),SESSION_CONTEXT(N'hp_tenant_id')),@found char(36); SELECT @found=id FROM dbo.users WITH(UPDLOCK,HOLDLOCK) WHERE id=@professional_id AND active=1; IF @t IS NULL OR @found IS NULL OR NOT EXISTS(SELECT 1 FROM dbo.memberships m JOIN dbo.membership_branches mb ON mb.tenant_id=m.tenant_id AND mb.user_id=m.user_id JOIN dbo.membership_specialties ms ON ms.tenant_id=m.tenant_id AND ms.user_id=m.user_id JOIN dbo.branches b ON b.tenant_id=mb.tenant_id AND b.id=mb.branch_id JOIN dbo.tenant_specialties ts ON ts.tenant_id=ms.tenant_id AND ts.specialty_code=ms.specialty_code JOIN dbo.tenants t ON t.id=m.tenant_id JOIN dbo.users u ON u.id=m.user_id WHERE m.tenant_id=@t AND m.user_id=@professional_id AND m.status='ACTIVE' AND mb.branch_id=@branch_id AND ms.specialty_code=@specialty_code AND b.active=1 AND u.clinical_domain=t.domain AND EXISTS(SELECT 1 FROM OPENJSON(m.roles) WHERE value COLLATE Latin1_General_100_BIN2='PRO')) THROW 51001,'HP_FORBIDDEN:Profesional sin asignacion activa de sede y especialidad',1;
END;
GO

-- PRIVATE PortalService.portal/link: current host membership + module and optional active link scope, held until audited read completes.
CREATE PROCEDURE dbo.usp_portal_scope @patient_id char(36)=NULL,@link_scope nvarchar(80)=NULL,@finance bit=0
AS
BEGIN
 SET NOCOUNT ON; SET XACT_ABORT ON;
 EXEC dbo.usp_clinical_scope N'PAC,RES'; EXEC dbo.usp_require_transaction; IF @link_scope IS NOT NULL AND @patient_id IS NULL THROW 51000,'HP_INVALID:Paciente de portal requerido',1; DECLARE @t char(36)=CONVERT(char(36),SESSION_CONTEXT(N'hp_tenant_id')),@u char(36)=CONVERT(char(36),SESSION_CONTEXT(N'hp_actor_id')); IF NOT EXISTS(SELECT 1 FROM dbo.subscriptions s JOIN dbo.plan_versions v ON v.plan_id=s.plan_id AND v.version=s.plan_version CROSS APPLY OPENJSON(v.modules) j WHERE s.tenant_id=@t AND j.value COLLATE Latin1_General_100_BIN2='PORTAL') THROW 51001,'HP_FORBIDDEN:Portal no incluido',1; IF @finance=1 AND NOT EXISTS(SELECT 1 FROM dbo.subscriptions s JOIN dbo.plan_versions v ON v.plan_id=s.plan_id AND v.version=s.plan_version CROSS APPLY OPENJSON(v.modules) j WHERE s.tenant_id=@t AND j.value COLLATE Latin1_General_100_BIN2='FINANCE') THROW 51001,'HP_FORBIDDEN:Finanzas no incluidas',1; IF @patient_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM dbo.patient_links l WITH(HOLDLOCK) WHERE l.tenant_id=@t AND l.user_id=@u AND l.patient_id=@patient_id AND l.active=1 AND EXISTS(SELECT 1 FROM OPENJSON(l.scopes) WHERE value COLLATE Latin1_General_100_BIN2=@link_scope COLLATE Latin1_General_100_BIN2)) THROW 51002,'HP_NOT_FOUND:Vinculo de portal no disponible',1;
END;
GO

-- PatientService.list: limit1..200, nonnegative offset; complete patient projection, own tenant only.
CREATE PROCEDURE dbo.usp_patients_list @query nvarchar(max)=N'',@limit int=100,@offset int=0
AS
BEGIN
 SET NOCOUNT ON; SET XACT_ABORT ON;
 EXEC dbo.usp_clinical_scope N'ADM,REC,PRO,ASI,AUD'; IF DATALENGTH(@query)>7996 THROW 51000,'HP_INVALID:Consulta demasiado extensa',1; DECLARE @t char(36)=CONVERT(char(36),SESSION_CONTEXT(N'hp_tenant_id')); SET @limit=CASE WHEN @limit IS NULL THEN 100 WHEN @limit<1 THEN 1 WHEN @limit>200 THEN 200 ELSE @limit END; SET @offset=CASE WHEN @offset IS NULL OR @offset<0 THEN 0 ELSE @offset END; SELECT id,tenant_id,name,domain,identifier,birth_date,species,contact,allergies,revision,created_at FROM dbo.patients WHERE tenant_id=@t AND (name LIKE N'%'+COALESCE(@query,N'')+N'%' OR identifier LIKE N'%'+COALESCE(@query,N'')+N'%') ORDER BY name,id OFFSET @offset ROWS FETCH NEXT @limit ROWS ONLY;
END;
GO

-- PatientService.get/save result + patient existence lookup: same tenant, no branch filter.
CREATE PROCEDURE dbo.usp_patient_get @patient_id char(36)
AS
BEGIN
 SET NOCOUNT ON; SET XACT_ABORT ON;
 EXEC dbo.usp_clinical_scope N'ADM,REC,PRO,ASI,AUD'; DECLARE @t char(36)=CONVERT(char(36),SESSION_CONTEXT(N'hp_tenant_id')); IF NOT EXISTS(SELECT 1 FROM dbo.patients WHERE tenant_id=@t AND id=@patient_id) THROW 51002,'HP_NOT_FOUND:Paciente inexistente',1; SELECT id,tenant_id,name,domain,identifier,birth_date,species,contact,allergies,revision,created_at FROM dbo.patients WHERE tenant_id=@t AND id=@patient_id;
END;
GO

-- PatientService.history: four resultsets encounters/entries/documents/limits+patient_id; longitudinal ALL branches of same tenant, never cross-tenant.
CREATE PROCEDURE dbo.usp_patient_history @patient_id char(36)
AS
BEGIN
 SET NOCOUNT ON; SET XACT_ABORT ON;
 EXEC dbo.usp_clinical_scope N'PRO,ASI,AUD'; EXEC dbo.usp_require_transaction; DECLARE @t char(36)=CONVERT(char(36),SESSION_CONTEXT(N'hp_tenant_id')); IF NOT EXISTS(SELECT 1 FROM dbo.patients WHERE tenant_id=@t AND id=@patient_id) THROW 51002,'HP_NOT_FOUND:Paciente inexistente',1; EXEC dbo.usp_audit_event @t,N'PATIENT_HISTORY_READ',@patient_id; SELECT TOP(200) id,tenant_id,patient_id,branch_id,professional_id,specialty_code,status,note,revision,profile_snapshot,created_at,finalized_at,active_patient FROM dbo.encounters WHERE tenant_id=@t AND patient_id=@patient_id ORDER BY created_at DESC,id; SELECT TOP(1000) c.id,c.tenant_id,c.encounter_id,c.kind,c.payload,c.profile_snapshot,c.actor_id,c.created_at FROM dbo.clinical_entries c JOIN dbo.encounters e ON e.tenant_id=c.tenant_id AND e.id=c.encounter_id WHERE c.tenant_id=@t AND e.patient_id=@patient_id ORDER BY c.created_at DESC,c.id; SELECT TOP(200) id,tenant_id,patient_id,encounter_id,title,type,content,status,revision,original_id,signer_id,signed_at,content_hash,published,withdrawn,created_at FROM dbo.documents WHERE tenant_id=@t AND patient_id=@patient_id ORDER BY created_at DESC,id; SELECT @patient_id patient_id,CAST(200 AS int) encounters_limit,CAST(1000 AS int) entries_limit,CAST(200 AS int) documents_limit;
END;
GO

-- ClinicalService.get/start/note: 2 resultsets encounter + entries, same-tenant longitudinal read without assignment narrowing.
CREATE PROCEDURE dbo.usp_encounter_get @encounter_id char(36)
AS
BEGIN
 SET NOCOUNT ON; SET XACT_ABORT ON;
 EXEC dbo.usp_clinical_scope N'PRO,ASI,AUD'; EXEC dbo.usp_require_transaction; DECLARE @t char(36)=CONVERT(char(36),SESSION_CONTEXT(N'hp_tenant_id')); IF NOT EXISTS(SELECT 1 FROM dbo.encounters WHERE tenant_id=@t AND id=@encounter_id) THROW 51002,'HP_NOT_FOUND:Atencion inexistente',1; EXEC dbo.usp_audit_event @t,N'ENCOUNTER_READ',@encounter_id; SELECT id,tenant_id,patient_id,branch_id,professional_id,specialty_code,status,note,revision,profile_snapshot,created_at,finalized_at,active_patient FROM dbo.encounters WHERE tenant_id=@t AND id=@encounter_id; SELECT id,tenant_id,encounter_id,kind,payload,profile_snapshot,actor_id,created_at FROM dbo.clinical_entries WHERE tenant_id=@t AND encounter_id=@encounter_id ORDER BY created_at,id;
END;
GO

-- DocumentService.list: same tenant across branches, audited internally, 200 complete documents.
CREATE PROCEDURE dbo.usp_documents_list @patient_id char(36)
AS
BEGIN
 SET NOCOUNT ON; SET XACT_ABORT ON;
 EXEC dbo.usp_clinical_scope N'PRO,ASI,AUD'; EXEC dbo.usp_require_transaction; DECLARE @t char(36)=CONVERT(char(36),SESSION_CONTEXT(N'hp_tenant_id')); IF NOT EXISTS(SELECT 1 FROM dbo.patients WHERE tenant_id=@t AND id=@patient_id) THROW 51002,'HP_NOT_FOUND:Paciente inexistente',1; EXEC dbo.usp_audit_event @t,N'DOCUMENT_LIST_READ',@patient_id; SELECT TOP(200) id,tenant_id,patient_id,encounter_id,title,type,content,status,revision,original_id,signer_id,signed_at,content_hash,published,withdrawn,created_at FROM dbo.documents WHERE tenant_id=@t AND patient_id=@patient_id ORDER BY created_at DESC,id;
END;
GO

-- DocumentService.get/create/change result: full document, internal audit, no body in audit metadata.
CREATE PROCEDURE dbo.usp_document_get @document_id char(36)
AS
BEGIN
 SET NOCOUNT ON; SET XACT_ABORT ON;
 EXEC dbo.usp_clinical_scope N'PRO,ASI,AUD'; EXEC dbo.usp_require_transaction; DECLARE @t char(36)=CONVERT(char(36),SESSION_CONTEXT(N'hp_tenant_id')); IF NOT EXISTS(SELECT 1 FROM dbo.documents WHERE tenant_id=@t AND id=@document_id) THROW 51002,'HP_NOT_FOUND:Documento inexistente',1; EXEC dbo.usp_audit_event @t,N'DOCUMENT_READ',@document_id; SELECT id,tenant_id,patient_id,encounter_id,title,type,content,status,revision,original_id,signer_id,signed_at,content_hash,published,withdrawn,created_at FROM dbo.documents WHERE tenant_id=@t AND id=@document_id;
END;
GO
-- PRIVATE strict DTO JSON shape with explicitly nullable properties; no SQL text dispatcher.
CREATE PROCEDURE dbo.usp_clinical_json_object @input nvarchar(max),@contract nvarchar(max),@nullable nvarchar(max)=N'[]'
AS
BEGIN
 SET NOCOUNT ON; SET XACT_ABORT ON;
 IF @input IS NULL OR ISJSON(@input,OBJECT)<>1 THROW 51000,'HP_INVALID:Objeto JSON requerido',1; IF EXISTS(SELECT [key] FROM OPENJSON(@input) GROUP BY [key] HAVING COUNT(*)>1) OR EXISTS(SELECT 1 FROM OPENJSON(@input) i LEFT JOIN OPENJSON(@contract) c ON c.[key]=i.[key] WHERE c.[key] IS NULL OR (i.type<>TRY_CONVERT(int,c.value) AND NOT(i.type=0 AND EXISTS(SELECT 1 FROM OPENJSON(@nullable) n WHERE n.value COLLATE Latin1_General_100_BIN2=i.[key])))) OR EXISTS(SELECT 1 FROM OPENJSON(@contract) c WHERE NOT EXISTS(SELECT 1 FROM OPENJSON(@input) i WHERE i.[key]=c.[key])) THROW 51000,'HP_INVALID:Campos JSON ausentes, repetidos o de tipo incorrecto',1;
END;
GO

-- PatientService.save / MySQL V3 sp_patient_save: create expected0/update expected>=1, domain fixed by tenant. RS full patient; Spring retains Checks.json depth validation.
CREATE PROCEDURE dbo.usp_patient_save @patient_id char(36),@input nvarchar(max),@expected_revision int=0
AS
BEGIN
 SET NOCOUNT ON; SET XACT_ABORT ON;
 EXEC dbo.usp_clinical_scope N'ADM,REC,PRO',@write=1; DECLARE @t char(36)=CONVERT(char(36),SESSION_CONTEXT(N'hp_tenant_id')),@domain nvarchar(6),@name nvarchar(max),@d nvarchar(max),@identifier nvarchar(max),@birth nvarchar(max),@species nvarchar(max),@contact nvarchar(max),@allergies nvarchar(max),@date date,@rev int;
 EXEC dbo.usp_clinical_json_object @input,N'{"name":1,"domain":1,"identifier":1,"birthDate":1,"species":1,"contact":5,"allergies":4}',N'["birthDate","species"]';
 SELECT @name=name,@d=domain,@identifier=identifier,@birth=birthDate,@species=species,@contact=contact,@allergies=allergies FROM OPENJSON(@input) WITH(name nvarchar(max),domain nvarchar(max),identifier nvarchar(max),birthDate nvarchar(max),species nvarchar(max),contact nvarchar(max) AS JSON,allergies nvarchar(max) AS JSON);
 SELECT @domain=domain FROM dbo.tenants WHERE id=@t; SET @date=TRY_CONVERT(date,@birth,23);
 IF @patient_id IS NULL OR @expected_revision IS NULL OR @expected_revision<0 OR NULLIF(LTRIM(RTRIM(@name)),N'') IS NULL OR DATALENGTH(@name)>320 OR NULLIF(LTRIM(RTRIM(@identifier)),N'') IS NULL OR DATALENGTH(@identifier)>200 OR @d COLLATE Latin1_General_100_BIN2<>@domain COLLATE Latin1_General_100_BIN2 OR DATALENGTH(@d)<>2*LEN(@d) OR DATALENGTH(@species)>160 OR (@domain='ANIMAL' AND NULLIF(LTRIM(RTRIM(@species)),N'') IS NULL) OR (@birth IS NOT NULL AND (@date IS NULL OR DATALENGTH(@birth)<>20 OR CONVERT(nvarchar(10),@date,23)<>@birth OR @date>CONVERT(date,SYSUTCDATETIME()))) OR DATALENGTH(@contact)>400000 THROW 51000,'HP_INVALID:Datos de paciente invalidos',1;
 IF EXISTS(SELECT 1 FROM OPENJSON(@allergies) WHERE type<>1 OR DATALENGTH(value)>320) OR EXISTS(SELECT value COLLATE Latin1_General_100_BIN2 FROM OPENJSON(@allergies) GROUP BY value COLLATE Latin1_General_100_BIN2 HAVING COUNT(*)>1) THROW 51000,'HP_INVALID:Lista de alergias invalida',1;
 SELECT @rev=revision FROM dbo.patients WITH(UPDLOCK,HOLDLOCK) WHERE tenant_id=@t AND id=@patient_id;
 IF @expected_revision=0 AND EXISTS(SELECT 1 FROM dbo.patients WHERE id=@patient_id) THROW 51003,'HP_CONFLICT:Paciente existente',1; IF @expected_revision>0 AND @rev IS NULL THROW 51002,'HP_NOT_FOUND:Paciente inexistente',1; IF @expected_revision>0 AND @rev<>@expected_revision THROW 51003,'HP_CONFLICT:Revision del paciente desactualizada',1;
 IF EXISTS(SELECT 1 FROM dbo.patients WITH(UPDLOCK,HOLDLOCK) WHERE tenant_id=@t AND identifier=@identifier AND id<>@patient_id) THROW 51003,'HP_CONFLICT:Identificador de paciente utilizado',1;
 IF @expected_revision=0 INSERT dbo.patients(id,tenant_id,name,domain,identifier,birth_date,species,contact,allergies) VALUES(@patient_id,@t,@name,@domain,@identifier,@date,@species,@contact,@allergies); ELSE UPDATE dbo.patients SET name=@name,identifier=@identifier,birth_date=@date,species=@species,contact=@contact,allergies=@allergies,revision=revision+1 WHERE tenant_id=@t AND id=@patient_id AND revision=@expected_revision;
 DECLARE @next int=@expected_revision+1,@meta nvarchar(max); SET @meta=(SELECT @next revision FOR JSON PATH,WITHOUT_ARRAY_WRAPPER); EXEC dbo.usp_audit_event @t,N'PATIENT_SAVED',@patient_id,@meta; EXEC dbo.usp_patient_get @patient_id;
END;
GO

-- PatientService.link / V3 sp_patient_link: own tenant active PAC/RES membership, valid scopes, grant/revoke audit, RS saved link; no expectedRevision in current Link DTO.
CREATE PROCEDURE dbo.usp_patient_link_save @patient_id char(36),@input nvarchar(max)
AS
BEGIN
 SET NOCOUNT ON; SET XACT_ABORT ON;
 EXEC dbo.usp_clinical_scope N'ADM,REC',@write=1,@module=N'PORTAL'; EXEC dbo.usp_org_json_object @input,N'{"userId":1,"relationship":1,"active":3,"scopes":4}'; DECLARE @t char(36)=CONVERT(char(36),SESSION_CONTEXT(N'hp_tenant_id')),@u nvarchar(max),@relationship nvarchar(max),@active bit,@scopes nvarchar(max); SELECT @u=userId,@relationship=relationship,@active=CASE WHEN active='true' THEN 1 ELSE 0 END,@scopes=scopes FROM OPENJSON(@input) WITH(userId nvarchar(max),relationship nvarchar(max),active nvarchar(max),scopes nvarchar(max) AS JSON); IF DATALENGTH(@u)<>72 OR TRY_CONVERT(uniqueidentifier,@u) IS NULL OR NULLIF(LTRIM(RTRIM(@relationship)),N'') IS NULL OR DATALENGTH(@relationship)>160 THROW 51000,'HP_INVALID:Datos de vinculo invalidos',1; EXEC dbo.usp_org_json_strings @scopes,20,N'["APPOINTMENTS","DOCUMENTS","BILLING"]'; IF NOT EXISTS(SELECT 1 FROM dbo.patients WHERE tenant_id=@t AND id=@patient_id) OR NOT EXISTS(SELECT 1 FROM dbo.memberships m JOIN dbo.users u ON u.id=m.user_id WHERE m.tenant_id=@t AND m.user_id=@u AND (@active=0 OR (m.status='ACTIVE' AND u.active=1)) AND u.platform_role IS NULL AND EXISTS(SELECT 1 FROM OPENJSON(m.roles) WHERE value IN ('PAC','RES'))) THROW 51002,'HP_NOT_FOUND:Paciente o cuenta de portal no disponible',1; IF EXISTS(SELECT 1 FROM dbo.patient_links WITH(UPDLOCK,HOLDLOCK) WHERE tenant_id=@t AND patient_id=@patient_id AND user_id=@u) UPDATE dbo.patient_links SET relationship=@relationship,active=@active,scopes=@scopes WHERE tenant_id=@t AND patient_id=@patient_id AND user_id=@u; ELSE INSERT dbo.patient_links(tenant_id,patient_id,user_id,relationship,active,scopes) VALUES(@t,@patient_id,@u,@relationship,@active,@scopes); DECLARE @meta nvarchar(max)=(SELECT @u userId,@active active FOR JSON PATH,WITHOUT_ARRAY_WRAPPER); EXEC dbo.usp_audit_event @t,N'PORTAL_LINK_CHANGED',@patient_id,@meta; SELECT tenant_id,patient_id,user_id,relationship,active,scopes FROM dbo.patient_links WHERE tenant_id=@t AND patient_id=@patient_id AND user_id=@u;
END;
GO
-- SchedulingService.list: fixed UTC window, optional authorized branch, tenant-wide when omitted, limit200.
CREATE PROCEDURE dbo.usp_appointments_list @from datetime2(6),@to datetime2(6),@branch_id char(36)=NULL
AS
BEGIN
 SET NOCOUNT ON; SET XACT_ABORT ON;
 EXEC dbo.usp_clinical_scope N'REC,PRO,ASI,AUD'; IF @from IS NULL OR @to IS NULL OR @to<=@from OR DATEDIFF_BIG(microsecond,@from,@to)/86400000000>93 THROW 51000,'HP_INVALID:Consulta como maximo 93 dias UTC',1; IF @branch_id IS NOT NULL EXEC dbo.usp_clinical_branch_guard @branch_id; DECLARE @t char(36)=CONVERT(char(36),SESSION_CONTEXT(N'hp_tenant_id')); SELECT TOP(200) id,tenant_id,patient_id,branch_id,professional_id,specialty_code,starts_at,ends_at,status,service,note,revision,request_key,request_hash FROM dbo.appointments WHERE tenant_id=@t AND starts_at>=@from AND starts_at<@to AND (@branch_id IS NULL OR branch_id=@branch_id) ORDER BY starts_at,id;
END;
GO

-- SchedulingService.get/row: current tenant, existing read policy does not add a branch assignment filter.
CREATE PROCEDURE dbo.usp_appointment_get @appointment_id char(36)
AS
BEGIN
 SET NOCOUNT ON; SET XACT_ABORT ON;
 EXEC dbo.usp_clinical_scope N'REC,PRO,ASI,AUD'; DECLARE @t char(36)=CONVERT(char(36),SESSION_CONTEXT(N'hp_tenant_id')); IF NOT EXISTS(SELECT 1 FROM dbo.appointments WHERE tenant_id=@t AND id=@appointment_id) THROW 51002,'HP_NOT_FOUND:Cita inexistente',1; SELECT id,tenant_id,patient_id,branch_id,professional_id,specialty_code,starts_at,ends_at,status,service,note,revision,request_key,request_hash FROM dbo.appointments WHERE tenant_id=@t AND id=@appointment_id;
END;
GO

-- SchedulingService.reserve (staff/portal) / V3: server SHA256 of exact Requests.Reserve serialization, same key+hash returns prior row. UTC body format yyyy-MM-dd HH:mm:ss.ffffff; global PRO lock, no foreign-tenant schedule details returned.
CREATE PROCEDURE dbo.usp_appointment_reserve @appointment_id char(36),@input nvarchar(max),@request_key nvarchar(max),@request_hash char(64),@portal bit=0
AS
BEGIN
 SET NOCOUNT ON; SET XACT_ABORT ON;
 IF @portal IS NULL THROW 51000,'HP_INVALID:Origen de reserva requerido',1; IF @portal=1 EXEC dbo.usp_clinical_scope N'PAC,RES',@write=1; ELSE EXEC dbo.usp_clinical_scope N'REC,PRO',@write=1;
 EXEC dbo.usp_org_json_object @input,N'{"patientId":1,"branchId":1,"professionalId":1,"specialtyCode":1,"startsAt":1,"endsAt":1,"status":1,"service":1,"note":1}';
 DECLARE @t char(36)=CONVERT(char(36),SESSION_CONTEXT(N'hp_tenant_id')),@patient nvarchar(max),@branch nvarchar(max),@pro nvarchar(max),@spec nvarchar(max),@ss nvarchar(max),@es nvarchar(max),@status nvarchar(max),@service nvarchar(max),@note nvarchar(max),@start datetime2(6),@end datetime2(6),@existing char(36),@hash char(64),@b char(36),@u char(36),@code varchar(100);
 SELECT @patient=patientId,@branch=branchId,@pro=professionalId,@spec=specialtyCode,@ss=startsAt,@es=endsAt,@status=status,@service=service,@note=note FROM OPENJSON(@input) WITH(patientId nvarchar(max),branchId nvarchar(max),professionalId nvarchar(max),specialtyCode nvarchar(max),startsAt nvarchar(max),endsAt nvarchar(max),status nvarchar(max),service nvarchar(max),note nvarchar(max));
 SET @start=TRY_CONVERT(datetime2(6),@ss,121); SET @end=TRY_CONVERT(datetime2(6),@es,121);
 IF @appointment_id IS NULL OR @request_key IS NULL OR LEN(@request_key) NOT BETWEEN 8 AND 100 OR DATALENGTH(@request_key)<>2*LEN(@request_key) OR @request_key COLLATE Latin1_General_100_BIN2 LIKE N'%[^-A-Za-z0-9_.:]%' OR @request_hash IS NULL OR LEN(@request_hash)<>64 OR @request_hash COLLATE Latin1_General_100_BIN2 LIKE '%[^0-9a-f]%' OR DATALENGTH(@patient)<>72 OR TRY_CONVERT(uniqueidentifier,@patient) IS NULL OR DATALENGTH(@branch)<>72 OR TRY_CONVERT(uniqueidentifier,@branch) IS NULL OR DATALENGTH(@pro)<>72 OR TRY_CONVERT(uniqueidentifier,@pro) IS NULL OR NULLIF(@spec,N'') IS NULL OR DATALENGTH(@spec)>200 OR @spec COLLATE Latin1_General_100_BIN2 LIKE N'%[^-A-Za-z0-9_:]%' OR DATALENGTH(@status)<>2*LEN(@status) OR @status COLLATE Latin1_General_100_BIN2 NOT IN ('REQUESTED','RESERVED') OR NULLIF(LTRIM(RTRIM(@service)),N'') IS NULL OR DATALENGTH(@service)>320 OR DATALENGTH(@note)>2000 OR @start IS NULL OR @end IS NULL OR DATALENGTH(@ss)<>52 OR DATALENGTH(@es)<>52 OR CONVERT(nvarchar(26),@start,121)<>@ss OR CONVERT(nvarchar(26),@end,121)<>@es OR @end<=@start OR DATEDIFF_BIG(microsecond,@start,@end)/60000000<5 OR DATEDIFF_BIG(microsecond,@start,@end)/60000000>480 THROW 51000,'HP_INVALID:Datos u horario de cita invalidos',1;
 SET @b=CONVERT(char(36),@branch); SET @u=CONVERT(char(36),@pro); SET @code=CONVERT(varchar(100),@spec);
 IF @portal=1 BEGIN IF @status<>'REQUESTED' THROW 51000,'HP_INVALID:El portal solo solicita citas',1; DECLARE @p char(36)=CONVERT(char(36),@patient); EXEC dbo.usp_portal_scope @p,N'APPOINTMENTS'; END ELSE EXEC dbo.usp_clinical_branch_guard @b;
 -- Serialize by tenant request key before returning any prior result. No repeat audit on replay.
 SELECT @existing=id,@hash=request_hash FROM dbo.appointments WITH(UPDLOCK,HOLDLOCK) WHERE tenant_id=@t AND request_key=@request_key;
 IF @existing IS NOT NULL BEGIN IF @hash<>@request_hash THROW 51003,'HP_CONFLICT:Clave de idempotencia utilizada con otros datos',1; SELECT id,tenant_id,patient_id,branch_id,professional_id,specialty_code,starts_at,ends_at,status,service,note,revision,request_key,request_hash FROM dbo.appointments WHERE tenant_id=@t AND id=@existing; RETURN; END;
 IF @start<DATEADD(second,-60,SYSUTCDATETIME()) THROW 51000,'HP_INVALID:Selecciona un horario futuro',1;
 EXEC dbo.usp_clinical_professional_guard @u,@b,@code;
 IF NOT EXISTS(SELECT 1 FROM dbo.patients WHERE tenant_id=@t AND id=@patient) THROW 51002,'HP_NOT_FOUND:Paciente inexistente',1;
 IF EXISTS(SELECT 1 FROM dbo.appointments WHERE professional_id=@u AND status NOT IN ('CANCELLED','WITHDRAWN') AND starts_at<@end AND ends_at>@start) THROW 51003,'HP_CONFLICT:Profesional ocupado en ese horario',1;
 INSERT dbo.appointments(id,tenant_id,patient_id,branch_id,professional_id,specialty_code,starts_at,ends_at,status,service,note,request_key,request_hash) VALUES(@appointment_id,@t,@patient,@b,@u,@code,@start,@end,@status,@service,@note,@request_key,@request_hash);
 EXEC dbo.usp_audit_event @t,N'APPOINTMENT_RESERVED',@appointment_id; SELECT id,tenant_id,patient_id,branch_id,professional_id,specialty_code,starts_at,ends_at,status,service,note,revision,request_key,request_hash FROM dbo.appointments WHERE tenant_id=@t AND id=@appointment_id;
END;
GO

-- SchedulingService.change + AppointmentStates / V3: state machine and expectedRevision, branch assignment, optional atomic reschedule. No SELECT Java needed after write.
CREATE PROCEDURE dbo.usp_appointment_change @appointment_id char(36),@expected_revision int,@status nvarchar(max),@starts_at datetime2(6)=NULL,@ends_at datetime2(6)=NULL
AS
BEGIN
 SET NOCOUNT ON; SET XACT_ABORT ON;
 EXEC dbo.usp_clinical_scope N'REC,PRO',@write=1;
 DECLARE @t char(36)=CONVERT(char(36),SESSION_CONTEXT(N'hp_tenant_id')),@pro char(36),@branch char(36),@spec varchar(100),@rev int,@old nvarchar(9),@locked char(36);
 SELECT @pro=professional_id FROM dbo.appointments WHERE tenant_id=@t AND id=@appointment_id; IF @pro IS NULL THROW 51002,'HP_NOT_FOUND:Cita inexistente',1;
 -- Same GLOBAL user lock order as reserve; take row write lock only after professional identity.
 SELECT @locked=id FROM dbo.users WITH(UPDLOCK,HOLDLOCK) WHERE id=@pro;
 SELECT @branch=branch_id,@spec=specialty_code,@rev=revision,@old=status FROM dbo.appointments WITH(UPDLOCK,HOLDLOCK) WHERE tenant_id=@t AND id=@appointment_id;
 EXEC dbo.usp_clinical_branch_guard @branch;
 IF @expected_revision IS NULL OR @expected_revision<1 OR @status IS NULL OR DATALENGTH(@status)<>2*LEN(@status) OR @status COLLATE Latin1_General_100_BIN2 NOT IN ('RESERVED','CONFIRMED','WAITING','CALLED','IN_CARE','COMPLETED','CANCELLED','WITHDRAWN') THROW 51000,'HP_INVALID:Revision o estado invalido',1;
 IF @rev<>@expected_revision THROW 51003,'HP_CONFLICT:La cita cambio; actualiza la vista',1;
 IF NOT ((@old='REQUESTED' AND @status IN ('RESERVED','CANCELLED')) OR (@old='RESERVED' AND @status IN ('RESERVED','CONFIRMED','CANCELLED')) OR (@old='CONFIRMED' AND @status IN ('RESERVED','WAITING','CANCELLED')) OR (@old='WAITING' AND @status IN ('CALLED','WITHDRAWN')) OR (@old='CALLED' AND @status IN ('IN_CARE','WAITING','WITHDRAWN')) OR (@old='IN_CARE' AND @status='COMPLETED')) THROW 51003,'HP_CONFLICT:Transicion de cita no permitida',1;
 IF @starts_at IS NOT NULL OR @ends_at IS NOT NULL BEGIN IF @starts_at IS NULL OR @ends_at IS NULL OR @ends_at<=@starts_at OR DATEDIFF_BIG(microsecond,@starts_at,@ends_at)/60000000<5 OR DATEDIFF_BIG(microsecond,@starts_at,@ends_at)/60000000>480 OR @starts_at<SYSUTCDATETIME() OR @status<>'RESERVED' THROW 51000,'HP_INVALID:Reprograma reserva a horario futuro valido',1; EXEC dbo.usp_clinical_professional_guard @pro,@branch,@spec; IF EXISTS(SELECT 1 FROM dbo.appointments WHERE id<>@appointment_id AND professional_id=@pro AND status NOT IN ('CANCELLED','WITHDRAWN') AND starts_at<@ends_at AND ends_at>@starts_at) THROW 51003,'HP_CONFLICT:El nuevo horario esta ocupado',1; END;
 UPDATE dbo.appointments SET starts_at=COALESCE(@starts_at,starts_at),ends_at=COALESCE(@ends_at,ends_at),status=@status,revision=revision+1 WHERE tenant_id=@t AND id=@appointment_id AND revision=@expected_revision;
 DECLARE @next int=@rev+1,@meta nvarchar(max); SET @meta=(SELECT @status status,@next revision FOR JSON PATH,WITHOUT_ARRAY_WRAPPER); EXEC dbo.usp_audit_event @t,N'APPOINTMENT_CHANGED',@appointment_id,@meta; SELECT id,tenant_id,patient_id,branch_id,professional_id,specialty_code,starts_at,ends_at,status,service,note,revision,request_key,request_hash FROM dbo.appointments WHERE tenant_id=@t AND id=@appointment_id;
END;
GO
-- ClinicalService.start / V3: one ACTIVE/PENDING per patient, snapshot complete catalog profile, current author PRO and assignments. RS encounter+entries.
CREATE PROCEDURE dbo.usp_encounter_start @encounter_id char(36),@input nvarchar(max)
AS
BEGIN
 SET NOCOUNT ON; SET XACT_ABORT ON;
 EXEC dbo.usp_clinical_scope N'PRO',@write=1; EXEC dbo.usp_org_json_object @input,N'{"patientId":1,"branchId":1,"specialtyCode":1}'; DECLARE @t char(36)=CONVERT(char(36),SESSION_CONTEXT(N'hp_tenant_id')),@u char(36)=CONVERT(char(36),SESSION_CONTEXT(N'hp_actor_id')),@patient nvarchar(max),@branch nvarchar(max),@spec nvarchar(max),@b char(36),@code varchar(100),@locked char(36),@profile nvarchar(max); SELECT @patient=patientId,@branch=branchId,@spec=specialtyCode FROM OPENJSON(@input) WITH(patientId nvarchar(max),branchId nvarchar(max),specialtyCode nvarchar(max)); IF @encounter_id IS NULL OR DATALENGTH(@patient)<>72 OR TRY_CONVERT(uniqueidentifier,@patient) IS NULL OR DATALENGTH(@branch)<>72 OR TRY_CONVERT(uniqueidentifier,@branch) IS NULL OR NULLIF(@spec,N'') IS NULL OR DATALENGTH(@spec)>200 OR @spec COLLATE Latin1_General_100_BIN2 LIKE N'%[^-A-Za-z0-9_:]%' THROW 51000,'HP_INVALID:Datos de atencion invalidos',1; SET @b=CONVERT(char(36),@branch); SET @code=CONVERT(varchar(100),@spec); EXEC dbo.usp_clinical_branch_guard @b; EXEC dbo.usp_clinical_professional_guard @u,@b,@code; SELECT @locked=id FROM dbo.patients WITH(UPDLOCK,HOLDLOCK) WHERE tenant_id=@t AND id=@patient; IF @locked IS NULL THROW 51002,'HP_NOT_FOUND:Paciente inexistente',1; IF EXISTS(SELECT 1 FROM dbo.encounters WITH(UPDLOCK,HOLDLOCK) WHERE tenant_id=@t AND patient_id=@patient AND status<>'FINALIZED') THROW 51003,'HP_CONFLICT:El paciente ya tiene atencion activa o pendiente',1; IF EXISTS(SELECT 1 FROM dbo.encounters WHERE id=@encounter_id) THROW 51003,'HP_CONFLICT:Atencion existente',1; SELECT @profile=profile FROM dbo.specialties WHERE code=@code; IF @profile IS NULL THROW 51002,'HP_NOT_FOUND:Perfil inexistente',1; INSERT dbo.encounters(id,tenant_id,patient_id,branch_id,professional_id,specialty_code,status,note,profile_snapshot) VALUES(@encounter_id,@t,@patient,@b,@u,@code,'ACTIVE',N'',@profile); EXEC dbo.usp_audit_event @t,N'ENCOUNTER_STARTED',@encounter_id; EXEC dbo.usp_encounter_get @encounter_id;
END;
GO

-- ClinicalService.note/finalize / V3 sp_encounter_save: author+branch+revision; preserves note MAX100000 UTF16 units, no text in audit. RS encounter+entries.
CREATE PROCEDURE dbo.usp_encounter_note @encounter_id char(36),@expected_revision int,@note nvarchar(max),@finalize bit=0
AS
BEGIN
 SET NOCOUNT ON; SET XACT_ABORT ON;
 EXEC dbo.usp_clinical_scope N'PRO',@write=1; DECLARE @t char(36)=CONVERT(char(36),SESSION_CONTEXT(N'hp_tenant_id')),@u char(36)=CONVERT(char(36),SESSION_CONTEXT(N'hp_actor_id')),@branch char(36),@author char(36),@status nvarchar(9),@rev int; IF @note IS NULL OR DATALENGTH(@note)>200000 OR @expected_revision IS NULL OR @expected_revision<1 OR @finalize IS NULL OR (@finalize=1 AND NULLIF(LTRIM(RTRIM(@note)),N'') IS NULL) THROW 51000,'HP_INVALID:Nota o revision de atencion invalida',1; SELECT @branch=branch_id,@author=professional_id,@status=status,@rev=revision FROM dbo.encounters WITH(UPDLOCK,HOLDLOCK) WHERE tenant_id=@t AND id=@encounter_id; IF @rev IS NULL OR @author<>@u THROW 51002,'HP_NOT_FOUND:Atencion no disponible para este profesional',1; EXEC dbo.usp_clinical_branch_guard @branch; IF @rev<>@expected_revision OR @status='FINALIZED' THROW 51003,'HP_CONFLICT:Atencion finalizada o revision desactualizada',1; UPDATE dbo.encounters SET note=@note,revision=revision+1,status=CASE WHEN @finalize=1 THEN 'FINALIZED' ELSE status END,finalized_at=CASE WHEN @finalize=1 THEN SYSUTCDATETIME() ELSE NULL END WHERE tenant_id=@t AND id=@encounter_id AND revision=@expected_revision; DECLARE @action nvarchar(80)=CASE WHEN @finalize=1 THEN N'ENCOUNTER_FINALIZED' ELSE N'ENCOUNTER_SAVED' END,@next int=@rev+1,@meta nvarchar(max); SET @meta=(SELECT @next revision FOR JSON PATH,WITHOUT_ARRAY_WRAPPER); EXEC dbo.usp_audit_event @t,@action,@encounter_id,@meta; EXEC dbo.usp_encounter_get @encounter_id;
END;
GO

-- ClinicalService.entry / V3: OBSERVATION PRO/ASI; other kinds author PRO. Spring MUST retain ClinicalValidation(profile fields/components/required/types/options) before calling. RS complete saved entry, no TODO rule engine substitution.
CREATE PROCEDURE dbo.usp_clinical_entry_add @entry_id char(36),@encounter_id char(36),@kind nvarchar(max),@payload nvarchar(max)
AS
BEGIN
 SET NOCOUNT ON; SET XACT_ABORT ON;
 IF @kind='OBSERVATION' EXEC dbo.usp_clinical_scope N'PRO,ASI',@write=1; ELSE EXEC dbo.usp_clinical_scope N'PRO',@write=1; IF @entry_id IS NULL OR @kind IS NULL OR DATALENGTH(@kind)<>2*LEN(@kind) OR @kind COLLATE Latin1_General_100_BIN2 NOT IN ('EVALUATION','OBSERVATION','ANNOTATION','ORDER','PRESCRIPTION') OR @payload IS NULL OR ISJSON(@payload,OBJECT)<>1 OR DATALENGTH(@payload)>400000 THROW 51000,'HP_INVALID:Tipo o captura clinica invalida',1; DECLARE @t char(36)=CONVERT(char(36),SESSION_CONTEXT(N'hp_tenant_id')),@u char(36)=CONVERT(char(36),SESSION_CONTEXT(N'hp_actor_id')),@branch char(36),@author char(36),@status nvarchar(9),@snapshot nvarchar(max),@component nvarchar(max); SELECT @branch=branch_id,@author=professional_id,@status=status,@snapshot=profile_snapshot FROM dbo.encounters WITH(UPDLOCK,HOLDLOCK) WHERE tenant_id=@t AND id=@encounter_id; IF @status IS NULL THROW 51002,'HP_NOT_FOUND:Atencion inexistente',1; EXEC dbo.usp_clinical_branch_guard @branch; IF @status='FINALIZED' THROW 51003,'HP_CONFLICT:La atencion esta finalizada',1; IF @kind<>'OBSERVATION' AND @author<>@u THROW 51001,'HP_FORBIDDEN:Entrada reservada al profesional de la atencion',1; SELECT @component=component FROM OPENJSON(@payload) WITH(component nvarchar(max)); IF @kind='ANNOTATION' AND @component COLLATE Latin1_General_100_BIN2 IN ('HUMAN_DENTAL','VET_DENTAL','PERIODONTAL','ENDO','ORTHODONTIC','PROSTHETIC') EXEC dbo.usp_write_guard @t,N'DENTAL'; INSERT dbo.clinical_entries(id,tenant_id,encounter_id,kind,payload,profile_snapshot,actor_id) VALUES(@entry_id,@t,@encounter_id,@kind,@payload,@snapshot,@u); DECLARE @meta nvarchar(max)=(SELECT @kind kind,@encounter_id encounterId FOR JSON PATH,WITHOUT_ARRAY_WRAPPER); EXEC dbo.usp_audit_event @t,N'CLINICAL_ENTRY_ADDED',@entry_id,@meta; SELECT id,tenant_id,encounter_id,kind,payload,profile_snapshot,actor_id,created_at FROM dbo.clinical_entries WHERE tenant_id=@t AND id=@entry_id;
END;
GO

-- DocumentService.create / V3: PRO tenant, signed original same patient/tenant and optional encounter same patient; no new branch restriction. Full MAX content, draft adenda only. RS document.
CREATE PROCEDURE dbo.usp_document_create @document_id char(36),@input nvarchar(max)
AS
BEGIN
 SET NOCOUNT ON; SET XACT_ABORT ON;
 EXEC dbo.usp_clinical_scope N'PRO',@write=1; EXEC dbo.usp_clinical_json_object @input,N'{"patientId":1,"encounterId":1,"title":1,"type":1,"content":1,"originalId":1}',N'["encounterId","originalId"]'; DECLARE @t char(36)=CONVERT(char(36),SESSION_CONTEXT(N'hp_tenant_id')),@patient nvarchar(max),@encounter nvarchar(max),@original nvarchar(max),@title nvarchar(max),@type nvarchar(max),@content nvarchar(max); SELECT @patient=patientId,@encounter=encounterId,@original=originalId,@title=title,@type=type,@content=content FROM OPENJSON(@input) WITH(patientId nvarchar(max),encounterId nvarchar(max),originalId nvarchar(max),title nvarchar(max),type nvarchar(max),content nvarchar(max)); IF @document_id IS NULL OR DATALENGTH(@patient)<>72 OR TRY_CONVERT(uniqueidentifier,@patient) IS NULL OR (@encounter IS NOT NULL AND (DATALENGTH(@encounter)<>72 OR TRY_CONVERT(uniqueidentifier,@encounter) IS NULL)) OR (@original IS NOT NULL AND (DATALENGTH(@original)<>72 OR TRY_CONVERT(uniqueidentifier,@original) IS NULL)) OR NULLIF(LTRIM(RTRIM(@title)),N'') IS NULL OR DATALENGTH(@title)>400 OR NULLIF(LTRIM(RTRIM(@type)),N'') IS NULL OR DATALENGTH(@type)>120 OR NULLIF(LTRIM(RTRIM(@content)),N'') IS NULL OR DATALENGTH(@content)>200000 THROW 51000,'HP_INVALID:Datos documentales invalidos',1; IF NOT EXISTS(SELECT 1 FROM dbo.patients WHERE tenant_id=@t AND id=@patient) THROW 51002,'HP_NOT_FOUND:Paciente inexistente',1; IF @original IS NOT NULL AND NOT EXISTS(SELECT 1 FROM dbo.documents WHERE tenant_id=@t AND id=@original AND patient_id=@patient AND status='SIGNED') THROW 51002,'HP_NOT_FOUND:Original firmado no disponible para este paciente',1; IF @encounter IS NOT NULL AND NOT EXISTS(SELECT 1 FROM dbo.encounters WHERE tenant_id=@t AND id=@encounter AND patient_id=@patient) THROW 51002,'HP_NOT_FOUND:Atencion no corresponde al paciente',1; INSERT dbo.documents(id,tenant_id,patient_id,encounter_id,title,type,content,status,original_id) VALUES(@document_id,@t,@patient,@encounter,@title,@type,@content,'DRAFT',@original); DECLARE @meta nvarchar(max)=(SELECT @original originalId FOR JSON PATH,WITHOUT_ARRAY_WRAPPER); EXEC dbo.usp_audit_event @t,N'DOCUMENT_CREATED',@document_id,@meta; EXEC dbo.usp_document_get @document_id;
END;
GO

-- DocumentService.change / V3: expectedRevision, immutable signatures and adendas, publication link check, withdrawal prevents future portal read. No raw text in general audit. RS document.
CREATE PROCEDURE dbo.usp_document_change @document_id char(36),@expected_revision int,@operation nvarchar(max),@content nvarchar(max)=NULL
AS
BEGIN
 SET NOCOUNT ON; SET XACT_ABORT ON;
 EXEC dbo.usp_clinical_scope N'PRO',@write=1; DECLARE @t char(36)=CONVERT(char(36),SESSION_CONTEXT(N'hp_tenant_id')),@u char(36)=CONVERT(char(36),SESSION_CONTEXT(N'hp_actor_id')),@status nvarchar(6),@rev int,@patient char(36),@stored nvarchar(max),@hash char(64); IF @expected_revision IS NULL OR @expected_revision<1 OR @operation IS NULL OR DATALENGTH(@operation)<>2*LEN(@operation) OR @operation COLLATE Latin1_General_100_BIN2 NOT IN ('SAVE','SIGN','PUBLISH','WITHDRAW') OR DATALENGTH(@content)>200000 THROW 51000,'HP_INVALID:Operacion documental invalida',1; SELECT @status=status,@rev=revision,@patient=patient_id,@stored=content FROM dbo.documents WITH(UPDLOCK,HOLDLOCK) WHERE tenant_id=@t AND id=@document_id; IF @rev IS NULL THROW 51002,'HP_NOT_FOUND:Documento inexistente',1; IF @rev<>@expected_revision THROW 51003,'HP_CONFLICT:Revision documental desactualizada',1; IF @operation IN ('SAVE','SIGN') AND @status<>'DRAFT' THROW 51003,'HP_CONFLICT:Documento firmado inmutable; utiliza una adenda',1;
 IF @operation='SAVE' BEGIN IF NULLIF(LTRIM(RTRIM(@content)),N'') IS NULL THROW 51000,'HP_INVALID:Escribe el contenido del borrador',1; UPDATE dbo.documents SET content=@content,revision=revision+1 WHERE tenant_id=@t AND id=@document_id; END
 ELSE IF @operation='SIGN' BEGIN
 -- HASHBYTES(NVARCHAR) hashes UTF16 and is WRONG for Checks.hash/MySQL SHA2.
 -- Explicit UTF8 VARCHAR collation preserves ASCII, accented text and supplementary emoji bytes.
 -- Verify expected SHA256 against Java StandardCharsets.UTF_8 for all three cases on engine.
 SET @hash=LOWER(CONVERT(char(64),HASHBYTES('SHA2_256',CONVERT(varchar(max),@stored COLLATE Latin1_General_100_BIN2_UTF8)),2));
 UPDATE dbo.documents SET status='SIGNED',signer_id=@u,signed_at=SYSUTCDATETIME(),content_hash=@hash,revision=revision+1 WHERE tenant_id=@t AND id=@document_id; END
 ELSE IF @operation='PUBLISH' BEGIN EXEC dbo.usp_write_guard @t,N'PORTAL'; IF @status<>'SIGNED' OR NOT EXISTS(SELECT 1 FROM dbo.patient_links l WITH(HOLDLOCK) WHERE l.tenant_id=@t AND l.patient_id=@patient AND l.active=1 AND EXISTS(SELECT 1 FROM OPENJSON(l.scopes) WHERE value COLLATE Latin1_General_100_BIN2='DOCUMENTS')) THROW 51003,'HP_CONFLICT:Se requiere firma y vinculo vigente de documentos',1; UPDATE dbo.documents SET published=1,withdrawn=0,revision=revision+1 WHERE tenant_id=@t AND id=@document_id; END
 ELSE UPDATE dbo.documents SET published=0,withdrawn=1,revision=revision+1 WHERE tenant_id=@t AND id=@document_id;
 DECLARE @action nvarchar(80)=N'DOCUMENT_'+@operation,@next int=@rev+1,@meta nvarchar(max); SET @meta=(SELECT @next revision FOR JSON PATH,WITHOUT_ARRAY_WRAPPER); EXEC dbo.usp_audit_event @t,@action,@document_id,@meta; EXEC dbo.usp_document_get @document_id;
END;
GO
-- PortalService.patients: active own links only, full scopes JSON, safe access audit added, external TX required even on read.
CREATE PROCEDURE dbo.usp_portal_patients
AS
BEGIN
 SET NOCOUNT ON; SET XACT_ABORT ON;
 EXEC dbo.usp_portal_scope; DECLARE @t char(36)=CONVERT(char(36),SESSION_CONTEXT(N'hp_tenant_id')),@u char(36)=CONVERT(char(36),SESSION_CONTEXT(N'hp_actor_id')); EXEC dbo.usp_audit_event @t,N'PORTAL_PATIENTS_READ',@u; SELECT p.id,p.name,p.domain,p.birth_date,p.species,l.relationship,l.scopes FROM dbo.patients p JOIN dbo.patient_links l WITH(HOLDLOCK) ON l.tenant_id=p.tenant_id AND l.patient_id=p.id WHERE p.tenant_id=@t AND l.user_id=@u AND l.active=1 ORDER BY p.name,p.id;
END;
GO

-- PortalService.documents: current own DOCUMENTS link and only published signed non-withdrawn documents; revocation denies later reads. Content MAX, safe audit.
CREATE PROCEDURE dbo.usp_portal_documents @patient_id char(36)
AS
BEGIN
 SET NOCOUNT ON; SET XACT_ABORT ON;
 EXEC dbo.usp_portal_scope @patient_id,N'DOCUMENTS'; DECLARE @t char(36)=CONVERT(char(36),SESSION_CONTEXT(N'hp_tenant_id')); EXEC dbo.usp_audit_event @t,N'PORTAL_DOCUMENTS_READ',@patient_id; SELECT TOP(200) id,title,type,content,revision,signer_id,signed_at,content_hash,original_id FROM dbo.documents WHERE tenant_id=@t AND patient_id=@patient_id AND published=1 AND withdrawn=0 AND status='SIGNED' ORDER BY signed_at DESC,id;
END;
GO

-- PortalService.appointments: own APPOINTMENTS scope, same limited public projection, internal audit added.
CREATE PROCEDURE dbo.usp_portal_appointments @patient_id char(36)
AS
BEGIN
 SET NOCOUNT ON; SET XACT_ABORT ON;
 EXEC dbo.usp_portal_scope @patient_id,N'APPOINTMENTS'; DECLARE @t char(36)=CONVERT(char(36),SESSION_CONTEXT(N'hp_tenant_id')); EXEC dbo.usp_audit_event @t,N'PORTAL_APPOINTMENTS_READ',@patient_id; SELECT TOP(200) id,branch_id,professional_id,specialty_code,starts_at,ends_at,status,service,revision FROM dbo.appointments WHERE tenant_id=@t AND patient_id=@patient_id ORDER BY starts_at DESC,id;
END;
GO

-- PortalService.balance: existing FINANCE+BILLING linked read only; no finance writes ported, refund sign semantics preserved.
CREATE PROCEDURE dbo.usp_portal_balance @patient_id char(36)
AS
BEGIN
 SET NOCOUNT ON; SET XACT_ABORT ON;
 EXEC dbo.usp_portal_scope @patient_id,N'BILLING',@finance=1; DECLARE @t char(36)=CONVERT(char(36),SESSION_CONTEXT(N'hp_tenant_id')); EXEC dbo.usp_audit_event @t,N'PORTAL_BALANCE_READ',@patient_id; SELECT COALESCE(SUM(CASE WHEN kind='PAYMENT' THEN -amount_minor ELSE amount_minor END),CONVERT(bigint,0)) balance_minor,CAST('PEN' AS char(3)) currency FROM dbo.finance_movements WHERE tenant_id=@t AND patient_id=@patient_id;
END;
GO

-- ==================== FIN V5__clinical_procedures.sql ====================

-- ==================== INICIO V6__operations_procedures.sql ====================
-- SQL Server 2022 operations persistence. Dependencies ONLY dbo tables + accepted V3/V4 helpers.
-- No V5 dependency; no provider/payment/SMTP side effects. Caller owns the Spring transaction.
-- Private operations_* helpers must not receive runtime EXECUTE grants.
SET ANSI_NULLS ON;
SET QUOTED_IDENTIFIER ON;
GO
-- PRIVATE Access.roles/module/write replacement. Never grants platform access to clinical/patient finance data.
CREATE PROCEDURE dbo.usp_operations_scope @roles nvarchar(200),@module nvarchar(40),@write bit=0
AS
BEGIN
 SET NOCOUNT ON; SET XACT_ABORT ON;
 EXEC dbo.usp_require_actor @roles;
 DECLARE @t char(36)=CONVERT(char(36),SESSION_CONTEXT(N'hp_tenant_id'));
 IF @t IS NULL THROW 51001,'HP_FORBIDDEN:Se requiere sesion tenant',1;
 IF @write=1 EXEC dbo.usp_write_guard @t,@module;
 ELSE IF NOT EXISTS(SELECT 1 FROM dbo.subscriptions s JOIN dbo.plan_versions v ON v.plan_id=s.plan_id AND v.version=s.plan_version CROSS APPLY OPENJSON(v.modules) j WHERE s.tenant_id=@t AND j.value COLLATE Latin1_General_100_BIN2=@module COLLATE Latin1_General_100_BIN2) THROW 51001,'HP_FORBIDDEN:Modulo no incluido',1;
END;
GO

-- PRIVATE current tenant active branch assignment via accepted V3; no V5 dependency.
CREATE PROCEDURE dbo.usp_operations_branch @branch_id char(36)
AS
BEGIN
 SET NOCOUNT ON; SET XACT_ABORT ON;
 DECLARE @allowed TABLE(id char(36),branch_id char(36)); INSERT @allowed EXEC dbo.usp_access_branch @branch_id; IF NOT EXISTS(SELECT 1 FROM @allowed) THROW 51001,'HP_FORBIDDEN:Sede no disponible para esta membresia',1;
END;
GO

-- PRIVATE strict JSON DTO types with nullable fields; no client SQL text.
CREATE PROCEDURE dbo.usp_operations_json @input nvarchar(max),@contract nvarchar(max),@nullable nvarchar(max)=N'[]'
AS
BEGIN
 SET NOCOUNT ON; SET XACT_ABORT ON;
 IF @input IS NULL OR ISJSON(@input,OBJECT)<>1 THROW 51000,'HP_INVALID:Objeto JSON requerido',1;
 IF EXISTS(SELECT [key] FROM OPENJSON(@input) GROUP BY [key] HAVING COUNT(*)>1) OR EXISTS(SELECT 1 FROM OPENJSON(@input) i LEFT JOIN OPENJSON(@contract) c ON c.[key]=i.[key] WHERE c.[key] IS NULL OR (i.type<>TRY_CONVERT(int,c.value) AND NOT(i.type=0 AND EXISTS(SELECT 1 FROM OPENJSON(@nullable) n WHERE n.value COLLATE Latin1_General_100_BIN2=i.[key])))) OR EXISTS(SELECT 1 FROM OPENJSON(@contract) c WHERE NOT EXISTS(SELECT 1 FROM OPENJSON(@input) i WHERE i.[key]=c.[key])) THROW 51000,'HP_INVALID:Campos ausentes, repetidos o de tipo incorrecto',1;
END;
GO

-- PRIVATE server Checks.hash + Idempotency.key contract. Stored hash only, never raw credentials.
CREATE PROCEDURE dbo.usp_operations_idempotency @request_key nvarchar(max),@request_hash char(64)
AS
BEGIN
 SET NOCOUNT ON; SET XACT_ABORT ON;
 IF @request_key IS NULL OR LEN(@request_key) NOT BETWEEN 8 AND 100 OR DATALENGTH(@request_key)<>2*LEN(@request_key) OR @request_key COLLATE Latin1_General_100_BIN2 LIKE N'%[^-A-Za-z0-9_.:]%' OR @request_hash IS NULL OR LEN(@request_hash)<>64 OR @request_hash COLLATE Latin1_General_100_BIN2 LIKE '%[^0-9a-f]%' THROW 51000,'HP_INVALID:Clave o hash de idempotencia invalido',1;
END;
GO

-- PRIVATE exact decimal parser for JSON BigDecimal, including exponent notation; rejects precision loss instead of rounding through FLOAT or DECIMAL casts.
CREATE PROCEDURE dbo.usp_operations_quantity @text nvarchar(max),@quantity decimal(14,3) OUTPUT
AS
BEGIN
 SET NOCOUNT ON; SET XACT_ABORT ON;
 IF @text IS NULL OR LEN(@text)>100 OR @text COLLATE Latin1_General_100_BIN2 LIKE N'%[^0-9.eE+-]%' THROW 51000,'HP_INVALID:Cantidad decimal invalida',1;
 DECLARE @e int=0,@pos int=CHARINDEX('e',LOWER(@text)),@mantissa nvarchar(100),@dot int,@scale int,@digits nvarchar(200),@normalized nvarchar(220);
 IF @pos>0 BEGIN SET @e=TRY_CONVERT(int,SUBSTRING(@text,@pos+1,100)); SET @mantissa=LEFT(@text,@pos-1); END ELSE SET @mantissa=@text;
 IF @e IS NULL OR @e NOT BETWEEN -100 AND 100 OR LEFT(@mantissa,1)='-' THROW 51000,'HP_INVALID:Cantidad positiva requerida',1;
 SET @dot=CHARINDEX('.',@mantissa); SET @scale=CASE WHEN @dot=0 THEN 0 ELSE LEN(@mantissa)-@dot END-@e; SET @digits=REPLACE(@mantissa,'.','');
 IF @digits=N'' OR @digits COLLATE Latin1_General_100_BIN2 LIKE N'%[^0-9]%' OR CHARINDEX('.',@mantissa,@dot+1)>0 THROW 51000,'HP_INVALID:Cantidad decimal invalida',1;
 WHILE LEN(@digits)>1 AND LEFT(@digits,1)='0' SET @digits=SUBSTRING(@digits,2,200);
 WHILE @scale>0 AND RIGHT(@digits,1)='0' AND LEN(@digits)>0 BEGIN SET @digits=LEFT(@digits,LEN(@digits)-1); SET @scale=@scale-1; END;
 IF @scale<0 BEGIN IF LEN(@digits)-@scale>11 THROW 51000,'HP_INVALID:Cantidad fuera de rango',1; SET @digits=@digits+REPLICATE(N'0',-@scale); SET @scale=0; END;
 IF @scale>3 OR LEN(@digits)-@scale>11 OR @digits=N'' THROW 51000,'HP_INVALID:Cantidad requiere hasta once enteros y tres decimales',1;
 IF @scale=0 SET @normalized=@digits; ELSE BEGIN WHILE LEN(@digits)<=@scale SET @digits=N'0'+@digits; SET @normalized=LEFT(@digits,LEN(@digits)-@scale)+N'.'+RIGHT(@digits,@scale); END;
 SET @quantity=TRY_CONVERT(decimal(14,3),@normalized); IF @quantity IS NULL OR @quantity<0.001 THROW 51000,'HP_INVALID:Cantidad positiva requerida',1;
END;
GO

-- FinanceService.balance: CAJ/AUD, no PRO permission dependency. Exact decimal38 aggregate avoids BIGINT SUM overflow; Java Number/monetary serialization unchanged.
CREATE PROCEDURE dbo.usp_finance_balance @patient_id char(36)
AS
BEGIN
 SET NOCOUNT ON; SET XACT_ABORT ON;
 EXEC dbo.usp_operations_scope N'CAJ,AUD',N'FINANCE';
 DECLARE @t char(36)=CONVERT(char(36),SESSION_CONTEXT(N'hp_tenant_id'));
 IF NOT EXISTS(SELECT 1 FROM dbo.patients WHERE tenant_id=@t AND id=@patient_id) THROW 51002,'HP_NOT_FOUND:Paciente inexistente',1;
 SELECT COALESCE(SUM(CASE WHEN kind='PAYMENT' THEN -CONVERT(decimal(38,0),amount_minor) ELSE CONVERT(decimal(38,0),amount_minor) END),CONVERT(decimal(38,0),0)) balance_minor,CAST('PEN' AS char(3)) currency FROM dbo.finance_movements WHERE tenant_id=@t AND patient_id=@patient_id;
END;
GO

-- FinanceService.movements: patient existence directly, not a clinical patient_get call; existing 200-row projection.
CREATE PROCEDURE dbo.usp_finance_movements @patient_id char(36)
AS
BEGIN
 SET NOCOUNT ON; SET XACT_ABORT ON;
 EXEC dbo.usp_operations_scope N'CAJ,AUD',N'FINANCE';
 DECLARE @t char(36)=CONVERT(char(36),SESSION_CONTEXT(N'hp_tenant_id'));
 IF NOT EXISTS(SELECT 1 FROM dbo.patients WHERE tenant_id=@t AND id=@patient_id) THROW 51002,'HP_NOT_FOUND:Paciente inexistente',1;
 SELECT TOP(200) id,tenant_id,patient_id,kind,amount_minor,currency,title,parent_id,actor_id,request_key,request_hash,created_at FROM dbo.finance_movements WHERE tenant_id=@t AND patient_id=@patient_id ORDER BY created_at DESC,id;
END;
GO

-- FinanceService.post / historical V4: patient + refund parent locks; existing same-key/hash returns row without new effects; no SaaS invoice or external charge.
CREATE PROCEDURE dbo.usp_finance_post @movement_id char(36),@input nvarchar(max),@request_key nvarchar(max),@request_hash char(64)
AS
BEGIN
 SET NOCOUNT ON; SET XACT_ABORT ON;
 EXEC dbo.usp_operations_scope N'CAJ',N'FINANCE',@write=1;
 EXEC dbo.usp_operations_idempotency @request_key,@request_hash;
 EXEC dbo.usp_operations_json @input,N'{"patientId":1,"kind":1,"amountMinor":2,"title":1,"parentId":1}',N'["parentId"]';
 DECLARE @t char(36)=CONVERT(char(36),SESSION_CONTEXT(N'hp_tenant_id')),@u char(36)=CONVERT(char(36),SESSION_CONTEXT(N'hp_actor_id')),@patient nvarchar(max),@kind nvarchar(max),@title nvarchar(max),@parent nvarchar(max),@raw nvarchar(max),@amount bigint,@pid char(36),@existing char(36),@hash char(64),@balance decimal(38,0),@paid bigint,@refunded decimal(38,0);
 SELECT @patient=patientId,@kind=kind,@title=title,@parent=parentId,@raw=amountMinor FROM OPENJSON(@input) WITH(patientId nvarchar(max),kind nvarchar(max),title nvarchar(max),parentId nvarchar(max),amountMinor nvarchar(max));
 SET @amount=TRY_CONVERT(bigint,@raw);
 IF @movement_id IS NULL OR DATALENGTH(@patient)<>72 OR TRY_CONVERT(uniqueidentifier,@patient) IS NULL OR @kind COLLATE Latin1_General_100_BIN2 NOT IN ('CHARGE','PAYMENT','REFUND') OR DATALENGTH(@kind)<>2*LEN(@kind) OR @amount IS NULL OR @amount NOT BETWEEN 1 AND 1000000000000 OR NULLIF(LTRIM(RTRIM(@title)),N'') IS NULL OR DATALENGTH(@title)>400 OR (@parent IS NOT NULL AND (DATALENGTH(@parent)<>72 OR TRY_CONVERT(uniqueidentifier,@parent) IS NULL)) THROW 51000,'HP_INVALID:Movimiento financiero invalido',1;
 SELECT @pid=id FROM dbo.patients WITH(UPDLOCK,HOLDLOCK) WHERE tenant_id=@t AND id=@patient;
 IF @pid IS NULL THROW 51002,'HP_NOT_FOUND:Paciente inexistente',1;
 SELECT @existing=id,@hash=request_hash FROM dbo.finance_movements WITH(UPDLOCK,HOLDLOCK) WHERE tenant_id=@t AND request_key=@request_key;
 IF @existing IS NOT NULL BEGIN IF @hash<>@request_hash THROW 51003,'HP_CONFLICT:Clave utilizada con otros datos',1;
 SELECT id,tenant_id,patient_id,kind,amount_minor,currency,title,parent_id,actor_id,request_key,request_hash,created_at FROM dbo.finance_movements WHERE tenant_id=@t AND id=@existing;
 RETURN;
 END;
 SELECT @balance=COALESCE(SUM(CASE WHEN kind='PAYMENT' THEN -CONVERT(decimal(38,0),amount_minor) ELSE CONVERT(decimal(38,0),amount_minor) END),0) FROM dbo.finance_movements WHERE tenant_id=@t AND patient_id=@pid;
 IF @kind='PAYMENT' AND @amount>@balance THROW 51003,'HP_CONFLICT:El pago excede el saldo pendiente',1;
 IF @kind='REFUND' BEGIN SELECT @paid=amount_minor FROM dbo.finance_movements WITH(UPDLOCK,HOLDLOCK) WHERE tenant_id=@t AND id=@parent AND patient_id=@pid AND kind='PAYMENT' AND currency='PEN';
 SELECT @refunded=COALESCE(SUM(CONVERT(decimal(38,0),amount_minor)),0) FROM dbo.finance_movements WHERE tenant_id=@t AND parent_id=@parent AND kind='REFUND';
 IF @paid IS NULL OR @amount>CONVERT(decimal(38,0),@paid)-@refunded THROW 51003,'HP_CONFLICT:Devolucion superior al pago disponible',1;
 END ELSE IF @parent IS NOT NULL THROW 51000,'HP_INVALID:Solo devolucion referencia un pago',1;
 INSERT dbo.finance_movements(id,tenant_id,patient_id,kind,amount_minor,currency,title,parent_id,actor_id,request_key,request_hash) VALUES(@movement_id,@t,@pid,@kind,@amount,'PEN',@title,@parent,@u,@request_key,@request_hash);
 DECLARE @meta nvarchar(max)=(SELECT @kind kind,@amount amountMinor FOR JSON PATH,WITHOUT_ARRAY_WRAPPER);
 EXEC dbo.usp_audit_event @t,N'FINANCE_POSTED',@movement_id,@meta;
 SELECT id,tenant_id,patient_id,kind,amount_minor,currency,title,parent_id,actor_id,request_key,request_hash,created_at FROM dbo.finance_movements WHERE tenant_id=@t AND id=@movement_id;
END;
GO
-- InventoryService.lots: 200 tenant lots in expiry/name order, full decimal quantity.
