IF OBJECT_ID(N'dbo.flyway_schema_history',N'U') IS NOT NULL
BEGIN
 DENY SELECT,INSERT,UPDATE,DELETE ON OBJECT::dbo.flyway_schema_history TO hp_runtime_executor;
