ALTER PROCEDURE dbo.usp_organization_member_save @tenant_id char(36),@user_id char(36),@input nvarchar(max)
AS
BEGIN
 SET NOCOUNT ON; SET XACT_ABORT ON;
 EXEC dbo.usp_org_target @tenant_id,@write=1; EXEC dbo.usp_org_json_object @input,N'{"roles":4,"status":1,"branches":4,"specialties":4}'; DECLARE @roles nvarchar(max),@status nvarchar(max),@branches nvarchar(max),@codes nvarchar(max),@domain nvarchar(6),@kind nvarchar(40),@ownerid char(36),@quota int,@used int,@owner bit,@oldpro bit=0,@newpro bit=0,@userdomain nvarchar(6); SELECT @roles=roles,@status=status,@branches=branches,@codes=specialties FROM OPENJSON(@input) WITH(roles nvarchar(max) AS JSON,status nvarchar(max),branches nvarchar(max) AS JSON,specialties nvarchar(max) AS JSON); EXEC dbo.usp_org_json_strings @roles,3,N'["ADM","REC","PRO","ASI","DIA","FAR","CAJ","ALM","PAC","RES","AUD"]'; EXEC dbo.usp_org_json_strings @branches,36; EXEC dbo.usp_org_json_strings @codes,100,@nonempty=0; IF DATALENGTH(@status)<>2*LEN(@status) OR @status COLLATE Latin1_General_100_BIN2 NOT IN ('ACTIVE','INVITED','INACTIVE') THROW 51000,'HP_INVALID:Estado de miembro invalido',1; SELECT @domain=domain,@kind=kind,@ownerid=owner_user_id FROM dbo.tenants WHERE id=@tenant_id; SELECT @quota=professional_quota FROM dbo.subscriptions WHERE tenant_id=@tenant_id; IF NOT EXISTS(SELECT 1 FROM dbo.users WITH(UPDLOCK,HOLDLOCK) WHERE id=@user_id AND active=1 AND platform_role IS NULL) THROW 51002,'HP_NOT_FOUND:Identidad no disponible',1; SELECT @userdomain=clinical_domain FROM dbo.users WHERE id=@user_id; SELECT @owner=owner,@oldpro=CASE WHEN status<>'INACTIVE' AND EXISTS(SELECT 1 FROM OPENJSON(roles) WHERE value='PRO') THEN 1 ELSE 0 END FROM dbo.memberships WITH(UPDLOCK,HOLDLOCK) WHERE tenant_id=@tenant_id AND user_id=@user_id; IF EXISTS(SELECT 1 FROM OPENJSON(@roles) WHERE value='PRO') BEGIN IF (@status<>'INACTIVE' AND (@userdomain IS NULL OR @userdomain<>@domain)) THROW 51000,'HP_INVALID:Identidad profesional incompatible',1; IF @kind='DOCTOR' AND @user_id<>@ownerid THROW 51003,'HP_CONFLICT:HP_QUOTA Una identidad clinica por profesional independiente',1; IF @status<>'INACTIVE' SET @newpro=1; END; SELECT @used=COUNT(*) FROM dbo.memberships m WHERE m.tenant_id=@tenant_id AND m.status<>'INACTIVE' AND EXISTS(SELECT 1 FROM OPENJSON(m.roles) WHERE value='PRO'); IF @newpro=1 AND @oldpro=0 AND @used>=@quota THROW 51003,'HP_CONFLICT:HP_QUOTA Sin licencias profesionales disponibles',1; IF @owner=1 AND (@status<>'ACTIVE' OR NOT EXISTS(SELECT 1 FROM OPENJSON(@roles) WHERE value='ADM')) THROW 51000,'HP_INVALID:Conserva administrador propietario activo',1; IF EXISTS(SELECT 1 FROM OPENJSON(@branches) j WHERE DATALENGTH(j.value)<>72 OR TRY_CONVERT(uniqueidentifier,j.value) IS NULL OR NOT EXISTS(SELECT 1 FROM dbo.branches b WHERE b.tenant_id=@tenant_id AND b.id=j.value COLLATE Latin1_General_100_BIN2 AND b.active=1)) THROW 51000,'HP_INVALID:Asigna sedes activas del mismo tenant',1; IF EXISTS(SELECT 1 FROM OPENJSON(@roles) WHERE value='PRO') AND ((@newpro=1 AND NOT EXISTS(SELECT 1 FROM OPENJSON(@codes))) OR EXISTS(SELECT 1 FROM OPENJSON(@codes) j WHERE NOT EXISTS(SELECT 1 FROM dbo.tenant_specialties ts WHERE ts.tenant_id=@tenant_id AND ts.specialty_code=j.value COLLATE Latin1_General_100_BIN2))) THROW 51000,'HP_INVALID:Asigna especialidades activadas del tenant',1; IF NOT EXISTS(SELECT 1 FROM dbo.memberships WHERE tenant_id=@tenant_id AND user_id=@user_id) INSERT dbo.memberships(tenant_id,user_id,roles,status,owner) VALUES(@tenant_id,@user_id,@roles,@status,0); ELSE UPDATE dbo.memberships SET roles=@roles,status=@status WHERE tenant_id=@tenant_id AND user_id=@user_id; DELETE dbo.membership_branches WHERE tenant_id=@tenant_id AND user_id=@user_id; INSERT dbo.membership_branches(tenant_id,user_id,branch_id) SELECT @tenant_id,@user_id,value FROM OPENJSON(@branches); DELETE dbo.membership_specialties WHERE tenant_id=@tenant_id AND user_id=@user_id; IF EXISTS(SELECT 1 FROM OPENJSON(@roles) WHERE value='PRO') INSERT dbo.membership_specialties(tenant_id,user_id,specialty_code) SELECT @tenant_id,@user_id,value FROM OPENJSON(@codes); DECLARE @meta nvarchar(max)=(SELECT @status status FOR JSON PATH,WITHOUT_ARRAY_WRAPPER); EXEC dbo.usp_audit_event @tenant_id,N'MEMBERSHIP_SAVED',@user_id,@meta; SELECT u.id,u.name,u.email,u.clinical_domain,m.roles,m.status,m.owner FROM dbo.memberships m JOIN dbo.users u ON u.id=m.user_id WHERE m.tenant_id=@tenant_id AND m.user_id=@user_id;
END;
GO

-- ==================== FIN V12__independent_professional_conflict.sql ====================

-- ==================== INICIO V13__patient_links_read.sql ====================
-- PAC-01.B1 / SQL Server 2022. ONE new public read and TWO object ACL entries.
-- Apply with a SEPARATE CONTROL principal in an EXTERNAL committable transaction.
-- The caller must stop at the first batch error (Flyway, or SQLcmd :On Error exit/-b).
-- GO separates CREATE PROCEDURE; never continue past a failed precondition.
-- No autonomous transaction, previous migration changes, data remediation or broad grants.
SET ANSI_NULLS ON;
SET QUOTED_IDENTIFIER ON;
SET XACT_ABORT ON;
IF @@TRANCOUNT=0 OR XACT_STATE()<>1
 THROW 51000,N'HP_INVALID:External migration transaction required',1;
IF ISNULL(HAS_PERMS_BY_NAME(DB_NAME(),N'DATABASE',N'CONTROL'),0)<>1
 OR ISNULL(IS_ROLEMEMBER(N'hp_runtime_executor'),0)=1
 OR ISNULL(IS_ROLEMEMBER(N'hp_bootstrap_executor'),0)=1
 THROW 51001,N'HP_FORBIDDEN:Separate administrative migration principal required',1;
IF NOT EXISTS(SELECT 1 FROM sys.schemas WHERE name COLLATE Latin1_General_100_BIN2=N'dbo' AND DATALENGTH(name)=6 AND principal_id=1)
 OR NOT EXISTS(SELECT 1 FROM sys.database_principals p JOIN sys.databases d ON d.database_id=DB_ID() AND p.sid=d.owner_sid
  WHERE p.name COLLATE Latin1_General_100_BIN2=N'dbo' AND DATALENGTH(p.name)=6 AND p.principal_id=1 AND DATALENGTH(p.sid)>0
  AND ((p.type COLLATE Latin1_General_100_BIN2='S' AND p.authentication_type=1)
    OR (p.type COLLATE Latin1_General_100_BIN2='U' AND p.authentication_type=3)))
 THROW 51000,N'HP_INVALID:Expected dbo ownership required',1;
IF (SELECT COUNT(*) FROM sys.database_principals WHERE name IN (N'hp_runtime_executor',N'hp_bootstrap_executor')
 AND type='R' AND is_fixed_role=0 AND owning_principal_id=DATABASE_PRINCIPAL_ID(N'dbo'))<>2
 THROW 51000,N'HP_INVALID:Expected execution roles required',1;
IF OBJECT_ID(N'dbo.usp_patient_links_list') IS NOT NULL
 THROW 51003,N'HP_CONFLICT:Patient links read entry already exists',1;
IF OBJECT_ID(N'dbo.usp_require_transaction',N'P') IS NULL
 OR OBJECT_ID(N'dbo.usp_clinical_scope',N'P') IS NULL
 OR OBJECT_ID(N'dbo.usp_require_actor',N'P') IS NULL
 OR OBJECT_ID(N'dbo.usp_audit_event',N'P') IS NULL
 THROW 51000,N'HP_INVALID:Accepted transaction and actor helpers required',1;
GO
CREATE PROCEDURE dbo.usp_patient_links_list
 @patient_id char(36), @limit int=50, @offset int=0
AS
BEGIN
 SET NOCOUNT ON;
 SET XACT_ABORT ON;
 EXEC dbo.usp_require_transaction;
 DECLARE @scope nvarchar(4000)=CONVERT(nvarchar(4000),SESSION_CONTEXT(N'hp_scope'));
 IF @scope IS NULL OR @scope COLLATE Latin1_General_100_BIN2<>N'REQUEST' OR DATALENGTH(@scope)<>14
  THROW 51001,N'HP_FORBIDDEN:Request scope required',1;
 EXEC dbo.usp_clinical_scope @roles=N'ADM,REC',@write=0;
 DECLARE @tenant char(36)=CONVERT(char(36),SESSION_CONTEXT(N'hp_tenant_id')),
         @actor char(36)=CONVERT(char(36),SESSION_CONTEXT(N'hp_actor_id')),
         @roles nvarchar(max);
 -- Hold the current DB membership until the caller completes the audited read.
 -- hp_actor_roles is NEVER an authorization source (the audit helper owns its capture).
 SELECT @roles=m.roles FROM dbo.memberships m WITH(HOLDLOCK)
 WHERE m.tenant_id=@tenant AND m.user_id=@actor AND m.status='ACTIVE';
 IF @tenant IS NULL OR @roles IS NULL
  OR NOT EXISTS(SELECT 1 FROM OPENJSON(@roles) WHERE type=1 AND value COLLATE Latin1_General_100_BIN2 IN (N'ADM',N'REC'))
  OR EXISTS(SELECT 1 FROM OPENJSON(@roles) WHERE type=1 AND value COLLATE Latin1_General_100_BIN2 IN (N'PAC',N'RES'))
  THROW 51001,N'HP_FORBIDDEN:Internal administrative membership required',1;
 IF @patient_id IS NULL OR TRY_CONVERT(uniqueidentifier,@patient_id) IS NULL
  OR @patient_id COLLATE Latin1_General_100_BIN2<>LOWER(CONVERT(char(36),TRY_CONVERT(uniqueidentifier,@patient_id))) COLLATE Latin1_General_100_BIN2
  THROW 51000,N'HP_INVALID:Canonical patient UUID required',1;
 IF NOT EXISTS(SELECT 1 FROM dbo.patients WITH(HOLDLOCK) WHERE tenant_id=@tenant AND id=@patient_id)
  THROW 51002,N'HP_NOT_FOUND:Paciente no disponible en este espacio',1;
 SET @limit=CASE WHEN @limit IS NULL THEN 50 WHEN @limit<1 THEN 1 WHEN @limit>200 THEN 200 ELSE @limit END;
 SET @offset=CASE WHEN @offset IS NULL OR @offset<0 THEN 0 ELSE @offset END;
 EXEC dbo.usp_audit_event @tenant_id=@tenant,@action=N'PATIENT_LINKS_READ',@target_id=@patient_id,@metadata=N'{}';
 -- Linked identities ONLY. Historical account/membership state does not hide a link.
 -- active describes the link; this read grants no portal, clinical or scope access.
 SELECT l.tenant_id,l.patient_id,l.user_id,u.name AS user_name,l.relationship,l.active,l.scopes
 FROM dbo.patient_links l
 JOIN dbo.users u ON u.id=l.user_id
 WHERE l.tenant_id=@tenant AND l.patient_id=@patient_id
 ORDER BY u.name,u.id
 OFFSET @offset ROWS FETCH NEXT @limit ROWS ONLY;
END;
GO
GRANT EXECUTE ON OBJECT::dbo.usp_patient_links_list TO hp_runtime_executor;
DENY EXECUTE ON OBJECT::dbo.usp_patient_links_list TO hp_bootstrap_executor;
GO

-- ==================== FIN V13__patient_links_read.sql ====================

-- ==================== INICIO V14__patient_link_revision.sql ====================
-- PAC-01.C1.P1 / SQL Server 2022, compatibility 160. OFFLINE PREPARATION ONLY.
-- NEW migration: +one revision column/default/check; ALTER existing writer;
-- CREATE one public edit reader; +two object EXECUTE ACLs. Never install with
-- the old API writer: C2 must first support expectedRevision and ACK5.
-- Caller owns ONE external committable transaction on ONE connection and MUST
-- stop on the first batch error (Flyway or SQLcmd :On Error exit / -b).
-- No BEGIN/COMMIT/ROLLBACK, repair/reapply, dynamic queries or new helper here.
-- Expected 134SP/564 role ACL ->135/566 only if that accepted baseline holds;
-- optional Flyway history permissions, when present, remain unchanged.
SET ANSI_NULLS ON;
SET QUOTED_IDENTIFIER ON;
SET XACT_ABORT ON;
SET NOCOUNT ON;
IF @@TRANCOUNT=0 OR XACT_STATE()<>1
 THROW 51000,N'HP_INVALID:External committable migration transaction required',1;
IF ISNULL(TRY_CONVERT(int,SERVERPROPERTY('ProductMajorVersion')),0)<>16
 OR ISNULL((SELECT compatibility_level FROM sys.databases WHERE database_id=DB_ID()),0)<>160
 THROW 51000,N'HP_INVALID:SQL Server 2022 compatibility160 required',1;
IF ISNULL(HAS_PERMS_BY_NAME(DB_NAME(),N'DATABASE',N'CONTROL'),0)<>1
 OR ISNULL(IS_ROLEMEMBER(N'hp_runtime_executor'),0)=1
 OR ISNULL(IS_ROLEMEMBER(N'hp_bootstrap_executor'),0)=1
 THROW 51001,N'HP_FORBIDDEN:Separate administrative migration principal required',1;
IF NOT EXISTS(SELECT 1 FROM sys.schemas WHERE name COLLATE Latin1_General_100_BIN2=N'dbo'
 AND DATALENGTH(name)=6 AND principal_id=1)
 OR NOT EXISTS(SELECT 1 FROM sys.database_principals p JOIN sys.databases d
 ON d.database_id=DB_ID() AND p.sid=d.owner_sid WHERE p.name COLLATE Latin1_General_100_BIN2=N'dbo'
 AND DATALENGTH(p.name)=6 AND p.principal_id=1 AND DATALENGTH(p.sid)>0
 AND ((p.type COLLATE Latin1_General_100_BIN2='S' AND p.authentication_type=1)
 OR (p.type COLLATE Latin1_General_100_BIN2='U' AND p.authentication_type=3)))
 THROW 51000,N'HP_INVALID:Expected dbo ownership required',1;
IF (SELECT COUNT(*) FROM sys.database_principals WHERE name IN (N'hp_runtime_executor',N'hp_bootstrap_executor')
 AND type='R' AND is_fixed_role=0 AND owning_principal_id=1)<>2
 OR EXISTS(SELECT 1 FROM sys.database_role_members WHERE member_principal_id IN
 (DATABASE_PRINCIPAL_ID(N'hp_runtime_executor'),DATABASE_PRINCIPAL_ID(N'hp_bootstrap_executor')))
 OR EXISTS(SELECT 1 FROM sys.schemas WHERE principal_id IN
 (DATABASE_PRINCIPAL_ID(N'hp_runtime_executor'),DATABASE_PRINCIPAL_ID(N'hp_bootstrap_executor')))
 OR EXISTS(SELECT 1 FROM sys.objects WHERE principal_id IN
 (DATABASE_PRINCIPAL_ID(N'hp_runtime_executor'),DATABASE_PRINCIPAL_ID(N'hp_bootstrap_executor')))
 THROW 51000,N'HP_INVALID:Expected execution roles and ownership chain required',1;
IF OBJECT_ID(N'dbo.usp_patient_link_edit_get') IS NOT NULL
 OR COL_LENGTH(N'dbo.patient_links',N'revision') IS NOT NULL
 OR OBJECT_ID(N'dbo.DF_patient_links_revision') IS NOT NULL
 OR OBJECT_ID(N'dbo.CK_patient_links_revision') IS NOT NULL
 THROW 51003,N'HP_CONFLICT:Link revision migration already present',1;

-- Exact accepted dependencies. Normalize CRLF or lone CR to LF and trim ONLY
-- outer ASCII space/tab/CR/LF. Accept the entire canonical GO batch (comments
-- included) OR the exact CREATE/ALTER statement without its known comment
-- prefix, because module storage/import boundaries can omit that prefix.
-- Never remove internal whitespace/comments, change keyword case, replace
-- CREATE/ALTER, or ignore an arbitrary prefix/suffix. Hash is UTF16LE SHA256.
DECLARE @modules TABLE(name sysname PRIMARY KEY,kind char(2),full_hash char(64),statement_hash char(64));
INSERT @modules(name,kind,full_hash,statement_hash) VALUES
 (N'usp_patient_link_save',N'P',N'C05D47ED844BF988FBB51B51599863C1FCD03A79B9B24F0987634E0B377C4C21',N'0CB4C21B6AB3ADFDA979156E130AF4BF767EFB796BC769888920125F7A19D2BC'),
 (N'trace_patient_links_change',N'TR',N'3AD3A51C6792B2E2AB46511C073DC2F4E35020DADF1B857D4BEC4F89BD3F62B9',N'EEBB88F94F14467171E3DA215265C0653DE1C84C91EF6F9A149E422732A3B775'),
 (N'usp_require_transaction',N'P',N'ED26307798A06C0AD45451707EFB4DD233BC236AF76F2C4CDA05207090AC3DD4',N'ED26307798A06C0AD45451707EFB4DD233BC236AF76F2C4CDA05207090AC3DD4'),
 (N'usp_require_actor',N'P',N'E2FF440DC1F4E36020B08AC7522F127F9CC1F0590F108F93E3F287E693E24C69',N'C0E38B8A3D8CB589B85EE61C53D72C5341CB4B196E2F3B95DAFF47352E536921'),
 (N'usp_write_guard',N'P',N'E92BD284EEA8DB194ACD849E6AD53C214B9AD2C9C6D521590835F8DE991BCE9E',N'4B61FD5E5295F8E75D5F5397BB08530D5887025022628311D8FE8958ACFAE3BE'),
 (N'usp_audit_event',N'P',N'85CAF28531CA043B4C93AC8164E4CC685C2364642A11032A9A5728BA6BD430E6',N'68C0931A743C9F0495BD28C54C10CDFB29295C2B924C022FA9DEB67C2C460FF4'),
 (N'usp_request_context',N'P',N'6041E70D99CF16EF7523DBC51336F2076FFE92285B5C0B7FA580D9D3CD5823E9',N'8D9AEECAEFC6CD286293342E4846B6C704EC257C8B927BB54A2921A7FE37542C'),
 (N'usp_clinical_scope',N'P',N'592E74E40833ADA4EB4904A275180F712982E55AD268972D2442431F2DFAE100',N'74EFAB8B6E1CE7DD7E96DD331C1D30534F0D35E9062A44366049AA71091D95D1'),
 (N'usp_patient_links_list',N'P',N'238A044649B952D40ABD1DAADD10AE1C49C596AF34DFDD7724CAD9F73EEF21AA',N'238A044649B952D40ABD1DAADD10AE1C49C596AF34DFDD7724CAD9F73EEF21AA');
IF EXISTS(SELECT 1 FROM @modules e LEFT JOIN sys.objects o
 ON o.object_id=OBJECT_ID(N'dbo.'+e.name) AND o.type COLLATE Latin1_General_100_BIN2=e.kind COLLATE Latin1_General_100_BIN2
 LEFT JOIN sys.sql_modules m ON m.object_id=o.object_id
 CROSS APPLY(SELECT TRIM(N' '+NCHAR(9)+NCHAR(10)+NCHAR(13) FROM
 REPLACE(REPLACE(m.definition,NCHAR(13)+NCHAR(10),NCHAR(10)),NCHAR(13),NCHAR(10))) AS normalized) n
 WHERE o.object_id IS NULL OR m.definition IS NULL OR o.is_ms_shipped<>0
 OR o.schema_id<>SCHEMA_ID(N'dbo') OR ISNULL(o.principal_id,1)<>1
 OR m.uses_ansi_nulls<>1 OR m.uses_quoted_identifier<>1
 OR m.execute_as_principal_id IS NOT NULL OR m.is_schema_bound<>0 OR m.is_recompiled<>0
 OR CONVERT(char(64),HASHBYTES('SHA2_256',CONVERT(varbinary(max),n.normalized)),2)
 COLLATE Latin1_General_100_BIN2 NOT IN (e.full_hash,e.statement_hash,CASE WHEN e.name=N'usp_require_transaction' THEN N'CE4B7FCEA8D43FA84999D7776652E26A65003B845D07F5B5743E1A3B7E7503FA' ELSE e.full_hash END))
 THROW 51000,N'HP_INVALID:Accepted link writer trigger or helper definition drift',1;
IF EXISTS(SELECT 1 FROM (VALUES(N'users'),(N'auth_sessions'),(N'memberships'),(N'tenants'),
 (N'subscriptions'),(N'plan_versions'),(N'patients'),(N'application_state'),(N'audit_events')) x(name)
 LEFT JOIN sys.tables t ON t.object_id=OBJECT_ID(N'dbo.'+x.name,N'U')
 WHERE t.object_id IS NULL OR ISNULL(t.principal_id,1)<>1)
 THROW 51000,N'HP_INVALID:Accepted dbo data dependencies required',1;

