IF EXISTS(SELECT 1 FROM @modules e LEFT JOIN sys.objects o ON o.object_id=OBJECT_ID(N'dbo.'+e.name)
 LEFT JOIN sys.sql_modules m ON m.object_id=o.object_id
 CROSS APPLY(SELECT TRIM(N' '+NCHAR(9)+NCHAR(10)+NCHAR(13) FROM REPLACE(REPLACE(m.definition,NCHAR(13)+NCHAR(10),NCHAR(10)),NCHAR(13),NCHAR(10))) normalized) n
 WHERE o.object_id IS NULL OR o.type NOT IN ('P','TR') OR o.schema_id<>SCHEMA_ID(N'dbo') OR ISNULL(o.principal_id,1)<>1
 OR m.definition IS NULL OR m.execute_as_principal_id IS NOT NULL OR m.uses_ansi_nulls<>1 OR m.uses_quoted_identifier<>1
 OR CONVERT(char(64),HASHBYTES('SHA2_256',CONVERT(varbinary(max),n.normalized)),2) COLLATE Latin1_General_100_BIN2 NOT IN (e.full_hash,e.statement_hash,CASE e.name WHEN N'usp_require_transaction' THEN N'CE4B7FCEA8D43FA84999D7776652E26A65003B845D07F5B5743E1A3B7E7503FA' WHEN N'usp_bootstrap_exists' THEN N'5FD46C5B861DFA36BC181B51A20CAEBA064C10F843D421493D2609C9422CB07B' WHEN N'usp_bootstrap_create' THEN N'94E3E5AF28CA7B7B74811D7F5E6D9467091C819E80868BB708443A71A73BDFEB' WHEN N'usp_saas_tenant_create' THEN N'4CC3F86A294BBF228E0281D3960B1C555E2112B305784256833F35CE43C8A93D' WHEN N'usp_organization_member_save' THEN N'23B980DB125443BB0620BAC1A7E7A816743640C9CA97225A26A9EE3843F5CDA3' WHEN N'usp_patient_link_save' THEN N'9BE3E5A61065191BF480AD83FE4E7FF18FD3825664F285C13C270A7082BFBF28' WHEN N'usp_appointments_list' THEN N'38F7B3B875D65CF60EF0AAE2DA39E7E0AA8D94423B1F3089760DED19299697D6' WHEN N'usp_inventory_transfer_receive' THEN N'7D52550977E2A3142AAAF4BF06F2E3930C6A61F9F50DD24EB0569F6E5ECD05D2' ELSE e.full_hash END))
 THROW 51000,N'HP_INVALID:Accepted V14 or dependency module definition drift',1;
DECLARE @t int=OBJECT_ID(N'dbo.tenants',N'U'),@l int=OBJECT_ID(N'dbo.patient_links',N'U');
IF @t IS NULL OR @l IS NULL OR (SELECT COUNT(*) FROM sys.columns WHERE object_id=@t)<>9 OR (SELECT COUNT(*) FROM sys.columns WHERE object_id=@l)<>7
 THROW 51000,N'HP_INVALID:Accepted tenant/link schema required',1;
DECLARE @shape TABLE(ordinal int,name sysname,type_name sysname,size smallint,collation_name sysname NULL,scale tinyint);
INSERT @shape VALUES (1,N'id',N'char',36,N'Latin1_General_100_BIN2',0),(2,N'name',N'nvarchar',320,N'Latin1_General_100_CI_AI_SC',0),(3,N'slug',N'varchar',63,N'Latin1_General_100_BIN2',0),(4,N'kind',N'nvarchar',32,N'Latin1_General_100_BIN2',0),(5,N'domain',N'nvarchar',12,N'Latin1_General_100_BIN2',0),(6,N'status',N'nvarchar',18,N'Latin1_General_100_BIN2',0),(7,N'owner_user_id',N'char',36,N'Latin1_General_100_BIN2',0),(8,N'timezone',N'nvarchar',128,N'Latin1_General_100_CI_AI_SC',0),(9,N'created_at',N'datetime2',8,NULL,6);
IF EXISTS(SELECT 1 FROM @shape e LEFT JOIN sys.columns c ON c.object_id=@t AND c.column_id=e.ordinal
 WHERE c.column_id IS NULL OR c.name COLLATE Latin1_General_100_BIN2<>e.name COLLATE Latin1_General_100_BIN2 OR TYPE_NAME(c.system_type_id)<>e.type_name OR c.user_type_id<>c.system_type_id OR c.max_length<>e.size OR c.scale<>e.scale OR c.is_nullable<>0 OR c.is_computed<>0 OR c.is_identity<>0 OR c.generated_always_type<>0 OR ISNULL(c.collation_name,N'') COLLATE Latin1_General_100_BIN2<>ISNULL(e.collation_name,N'') COLLATE Latin1_General_100_BIN2)
 OR NOT EXISTS(SELECT 1 FROM sys.columns WHERE object_id=@l AND column_id=7 AND name=N'revision' AND system_type_id=56 AND user_type_id=56 AND is_nullable=0 AND is_computed=0)
 OR NOT EXISTS(SELECT 1 FROM sys.default_constraints WHERE parent_object_id=@l AND parent_column_id=7 AND name=N'DF_patient_links_revision' AND definition IN (N'(1)',N'((1))'))
 OR NOT EXISTS(SELECT 1 FROM sys.check_constraints WHERE parent_object_id=@l AND name=N'CK_patient_links_revision' AND is_disabled=0 AND is_not_trusted=0 AND REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(definition,N'[',N''),N']',N''),N'(',N''),N')',N''),N' ',N'') COLLATE Latin1_General_100_BIN2=N'revision>=1')
 THROW 51000,N'HP_INVALID:Accepted tenant columns or V14 revision constraints required',1;
IF NOT EXISTS(SELECT 1 FROM sys.key_constraints WHERE parent_object_id=@t AND name=N'PK_tenants' AND type='PK')
 OR NOT EXISTS(SELECT 1 FROM sys.key_constraints WHERE parent_object_id=@t AND name=N'UQ_tenants_1' AND type='UQ')
 OR NOT EXISTS(SELECT 1 FROM sys.foreign_keys WHERE parent_object_id=@t AND name=N'FK_tenants_1' AND is_disabled=0 AND is_not_trusted=0)
 THROW 51000,N'HP_INVALID:Accepted stable tenant identity and owner relationship required',1;
IF NOT EXISTS(SELECT 1 FROM sys.database_permissions WHERE class=1 AND major_id=OBJECT_ID(N'dbo.usp_patient_link_edit_get') AND grantee_principal_id=DATABASE_PRINCIPAL_ID(N'hp_runtime_executor') AND permission_name=N'EXECUTE' AND state='G')
 OR NOT EXISTS(SELECT 1 FROM sys.database_permissions WHERE class=1 AND major_id=OBJECT_ID(N'dbo.usp_patient_link_edit_get') AND grantee_principal_id=DATABASE_PRINCIPAL_ID(N'hp_bootstrap_executor') AND permission_name=N'EXECUTE' AND state='D')
 OR EXISTS(SELECT 1 FROM sys.database_permissions WHERE grantee_principal_id IN (DATABASE_PRINCIPAL_ID(N'hp_runtime_executor'),DATABASE_PRINCIPAL_ID(N'hp_bootstrap_executor')) AND (state='W' OR (state='G' AND (class<>1 OR permission_name<>N'EXECUTE') AND permission_name<>N'CONNECT' AND NOT(class=1 AND major_id=ISNULL(OBJECT_ID(N'dbo.flyway_schema_history',N'U'),-1) AND permission_name=N'VIEW DEFINITION' AND grantee_principal_id=DATABASE_PRINCIPAL_ID(N'hp_runtime_executor')))))
 THROW 51000,N'HP_INVALID:Accepted object-only runtime execution ACL required',1;

