 WHERE NOT EXISTS(SELECT 1 FROM sys.database_permissions actual WHERE actual.class=1 AND actual.major_id=OBJECT_ID(N'dbo.'+e.name,N'P') AND actual.minor_id=0 AND actual.grantee_principal_id=expected.role_id AND actual.permission_name=N'EXECUTE' AND actual.state COLLATE Latin1_General_100_BIN2=expected.state COLLATE Latin1_General_100_BIN2))
 OR EXISTS(SELECT 1 FROM sys.database_role_members WHERE member_principal_id IN(DATABASE_PRINCIPAL_ID(N'hp_runtime_executor'),DATABASE_PRINCIPAL_ID(N'hp_bootstrap_executor')))
 OR EXISTS(SELECT 1 FROM sys.database_permissions WHERE grantee_principal_id=DATABASE_PRINCIPAL_ID(N'public') AND state IN ('G','W') AND ((class=0 AND permission_name NOT IN(N'CONNECT',N'VIEW ANY COLUMN ENCRYPTION KEY DEFINITION',N'VIEW ANY COLUMN MASTER KEY DEFINITION')) OR (class=3 AND major_id=SCHEMA_ID(N'dbo')) OR (class=1 AND OBJECT_SCHEMA_NAME(major_id)=N'dbo')))
 THROW 51000,N'HP_INVALID:Accepted V14 public/private execution ACL required',1;
